def create_qsfp_service_warmboot_and_reset_playbook(
    iteration: int = 5,
    post_warmboot_wait_seconds: int = 300,
    post_reset_settle_seconds: int = 300,
) -> Playbook:
    """Build the `test_qsfp_service_warmboot_and_reset` Playbook.

    Each cycle warmboots `qsfp_service`, holds, then resets every transceiver
    on the DUT via `wedge_qsfp_util --qsfp-reset`, exercising the optics
    daemon's ability to re-discover and re-program modules that were reset out
    from under it shortly after a warm boot.

    `Service.QSFP_SERVICE` + `SYSTEMCTL_RESTART` is inherently a warm boot:
    `create_cold_boot_file` only touches the wedge_agent path
    (`/dev/shm/fboss/warm_boot/cold_boot_once_0`), never qsfp_service's own
    `cold_boot_once_qsfp_service`.

    The reset defaults to `RESET_THEN_CLEAR`, so it self-clears and needs no
    paired enable step, but optics take several minutes to relink — hence the
    settle and convergence before postchecks run.

    Args:
        iteration: Number of warmboot + reset cycles. Default 5.
        post_warmboot_wait_seconds: Hold between the warmboot and the reset.
        post_reset_settle_seconds: Hold after the reset for optics to relink.

    Returns:
        A `Playbook` named `test_qsfp_service_warmboot_and_reset`.
    """
    return Playbook(
        name="test_qsfp_service_warmboot_and_reset",
        postchecks=[
            QSFP_SERVICE_RESTART_SERVICE_CHECK,
            _unclean_exit_check(["qsfp_service"]),
            create_port_state_check(),
            create_port_transceiver_check(),
        ],
        stages=[
            create_steps_stage(
                iteration=iteration,
                steps=[
                    create_service_interruption_step(
                        service=Service.QSFP_SERVICE,
                        trigger=ServiceInterruptionTrigger.SYSTEMCTL_RESTART,
                        description="Warmboot qsfp_service",
                    ),
                    create_longevity_step(
                        duration=post_warmboot_wait_seconds,
                        description=(
                            f"Hold {post_warmboot_wait_seconds}s after the "
                            "qsfp_service warmboot"
                        ),
                    ),
                    create_interface_flap_step(
                        enable=False,
                        interface_flap_method=int(
                            taac_types.InterfaceFlapMethod.FBOSS_WEDGE_QSFP_RESET
                        ),
                        jq_params={"interfaces": '."{dut}".interfaces'},
                        description=(
                            "Reset all transceivers in one "
                            "`wedge_qsfp_util --qsfp-reset` invocation"
                        ),
                    ),
                    create_longevity_step(
                        duration=post_reset_settle_seconds,
                        description=(
                            f"Settle {post_reset_settle_seconds}s for optics to "
                            "relink after the reset"
                        ),
                    ),
                    create_service_convergence_step(
                        services=[Service.QSFP_SERVICE, Service.AGENT, Service.BGP],
                        description=(
                            "Wait for qsfp_service, wedge_agent and bgpd to converge"
                        ),
                    ),
                    create_longevity_step(duration=30),
                ],
            ),
        ],
    )


def create_qsfp_service_warmboot_and_agent_coldboot_playbook(
    iteration: int = 5,
    post_warmboot_wait_seconds: int = 300,
) -> Playbook:
    """Build the `test_qsfp_service_warmboot_and_agent_coldboot` Playbook.

    Each cycle warmboots `qsfp_service`, holds, then coldboots the FBOSS agent,
    forcing the agent to rebuild hardware state from scratch against optics
    that qsfp_service only just re-enumerated.

    Coldboot is `SYSTEMCTL_RESTART` plus `create_cold_boot_file=True`, which
    drops `/dev/shm/fboss/warm_boot/cold_boot_once_0` — the same idiom as
    `create_agent_coldboot_playbook`. The agent restart cascades (BindsTo) to
    bgpd / fboss_sw_agent / fboss_hw_agent@0 and takes openr down with it, so
    all of those are declared as expected restarts.

    Args:
        iteration: Number of warmboot + coldboot cycles. Default 5.
        post_warmboot_wait_seconds: Hold between the qsfp_service warmboot and
            the agent coldboot.

    Returns:
        A `Playbook` named `test_qsfp_service_warmboot_and_agent_coldboot`.
    """
    return Playbook(
        name="test_qsfp_service_warmboot_and_agent_coldboot",
        postchecks=[
            create_service_restart_health_check(
                DEFAULT_SERVICE_NAMES,
                expected_restarted_services=[
                    "qsfp_service",
                    "wedge_agent",
                    "fboss_sw_agent",
                    "fboss_hw_agent@0",
                    "bgpd",
                    "openr",
                ],
            ),
        ],
        stages=[
            create_steps_stage(
                iteration=iteration,
                steps=[
                    create_service_interruption_step(
                        service=Service.QSFP_SERVICE,
                        trigger=ServiceInterruptionTrigger.SYSTEMCTL_RESTART,
                        description="Warmboot qsfp_service",
                    ),
                    create_longevity_step(
                        duration=post_warmboot_wait_seconds,
                        description=(
                            f"Hold {post_warmboot_wait_seconds}s after the "
                            "qsfp_service warmboot"
                        ),
                    ),
                    create_service_interruption_step(
                        service=Service.AGENT,
                        trigger=ServiceInterruptionTrigger.SYSTEMCTL_RESTART,
                        create_cold_boot_file=True,
                        description="Coldboot the FBOSS agent",
                    ),
                    create_service_convergence_step(
                        services=[Service.AGENT, Service.BGP],
                        description="Wait for wedge_agent and bgpd to converge",
                    ),
                ],
            ),
        ],
    )


def create_qsfp_service_warmboot_and_tx_flap_playbook(
    iteration: int = 5,
    post_warmboot_wait_seconds: int = 300,
    tx_down_seconds: int = 30,
    post_flap_settle_seconds: int = 300,
) -> Playbook:
    """Build the `test_qsfp_service_warmboot_and_tx_flap` Playbook.

    Each cycle warmboots `qsfp_service`, holds, then flaps every transceiver's
    laser off and back on via `wedge_qsfp_util --tx_disable` /
    `--tx_enable`, exercising link re-establishment against an optics daemon
    that recently warm-booted.

    Unlike the `--qsfp-reset` variant, a TX flap needs an explicit paired
    enable step — `--tx_disable` holds the laser off until something turns it
    back on.

    Args:
        iteration: Number of warmboot + flap cycles. Default 5.
        post_warmboot_wait_seconds: Hold between the warmboot and the flap.
        tx_down_seconds: How long the lasers stay disabled.
        post_flap_settle_seconds: Hold after re-enabling TX for links to recover.

    Returns:
        A `Playbook` named `test_qsfp_service_warmboot_and_tx_flap`.
    """
    return Playbook(
        name="test_qsfp_service_warmboot_and_tx_flap",
        postchecks=[
            QSFP_SERVICE_RESTART_SERVICE_CHECK,
            _unclean_exit_check(["qsfp_service"]),
        ],
        stages=[
            create_steps_stage(
                iteration=iteration,
                steps=[
                    create_service_interruption_step(
                        service=Service.QSFP_SERVICE,
                        trigger=ServiceInterruptionTrigger.SYSTEMCTL_RESTART,
                        description="Warmboot qsfp_service",
                    ),
                    create_longevity_step(
                        duration=post_warmboot_wait_seconds,
                        description=(
                            f"Hold {post_warmboot_wait_seconds}s after the "
                            "qsfp_service warmboot"
                        ),
                    ),
                    create_interface_flap_step(
                        enable=False,
                        interface_flap_method=int(
                            taac_types.InterfaceFlapMethod.FBOSS_WEDGE_QSFP_UTIL_TX
                        ),
                        delay=tx_down_seconds,
                        jq_params={"interfaces": '."{dut}".interfaces'},
                        description=(
                            "Disable TX on all transceivers in one "
                            "`wedge_qsfp_util --tx_disable` invocation"
                        ),
                    ),
                    create_interface_flap_step(
                        enable=True,
                        interface_flap_method=int(
                            taac_types.InterfaceFlapMethod.FBOSS_WEDGE_QSFP_UTIL_TX
                        ),
                        jq_params={"interfaces": '."{dut}".interfaces'},
                        description=(
                            "Re-enable TX on all transceivers in one "
                            "`wedge_qsfp_util --tx_enable` invocation"
                        ),
                    ),
                    create_longevity_step(
                        duration=post_flap_settle_seconds,
                        description=(
                            f"Settle {post_flap_settle_seconds}s for links to "
                            "recover after the TX flap"
                        ),
                    ),
                    create_service_convergence_step(
                        services=[Service.QSFP_SERVICE, Service.AGENT, Service.BGP],
                        description=(
                            "Wait for qsfp_service, wedge_agent and bgpd to converge"
                        ),
                    ),
                ],
            ),
        ],
    )


def create_agent_warmboot_wedge_and_sw_agent_playbook(
    iteration: int = 5,
) -> Playbook:
    """Build the `test_agent_warmboot_wedge_and_sw_agent` Playbook.

    Each cycle warmboots `wedge_agent`, waits for the agent and bgpd to
    reconverge, then warmboots `fboss_sw_agent` and waits for convergence
    again. The convergence gate *between* the two restarts is the point of
    this playbook: `TEST_SW_AGENT_AND_WEDGE_AGENT_RESTART_PLAYBOOK` fires both
    restarts back to back with a single convergence at the end, so it never
    exercises a second agent restart against a fully reconverged box.

    Warmboot semantics: `SYSTEMCTL_RESTART` with no `create_cold_boot_file`.

    The postcheck must be `AGENT_WARMBOOT_SERVICE_CHECK` (or another check
    declaring the full cascade). Restarting wedge_agent also restarts bgpd
    (`BindsTo`) plus fboss_sw_agent and fboss_hw_agent@0 (via the wedge_agent
    unit's `ExecStop` hook), and `test_service_restart_dependency` enforces
    fleet-wide that all four appear in `expected_restarted_services`.

    Args:
        iteration: Number of wedge_agent + fboss_sw_agent warmboot cycles.

    Returns:
        A `Playbook` named `test_agent_warmboot_wedge_and_sw_agent`.
    """
    return Playbook(
        name="test_agent_warmboot_wedge_and_sw_agent",
        stages=[
            create_steps_stage(
                iteration=iteration,
                steps=[
                    create_service_interruption_step(
                        service=Service.AGENT,
                        trigger=ServiceInterruptionTrigger.SYSTEMCTL_RESTART,
                        description="Warmboot wedge_agent",
                    ),
                    create_service_convergence_step(
                        services=[Service.AGENT, Service.BGP],
                        description=(
                            "Wait for the agent and bgpd to converge before "
                            "restarting fboss_sw_agent"
                        ),
                    ),
                    create_service_interruption_step(
                        service=Service.FBOSS_SW_AGENT,
                        trigger=ServiceInterruptionTrigger.SYSTEMCTL_RESTART,
                        description="Warmboot fboss_sw_agent",
                    ),
                    create_service_convergence_step(
                        services=[Service.AGENT, Service.BGP],
                        description=(
                            "Wait for the agent and bgpd to converge before the "
                            "next cycle"
                        ),
                    ),
                ],
            ),
        ],
    )


def create_fboss_hw_agent_0_coldboot_playbook(
    iteration: int = 15,
) -> Playbook:
    """Build the `test_fboss_hw_agent_0_coldboot` Playbook.

    Repeats `iteration` coldboots of `fboss_hw_agent@0`, waiting for the agent
    and bgpd to reconverge after each one before firing the next.

    Coldboot is `SYSTEMCTL_RESTART` plus `create_cold_boot_file=True`, which
    drops `/dev/shm/fboss/warm_boot/cold_boot_once_0`. The `_0` suffix is
    hw_agent switch index 0, so this is the right cold-boot flag here.

    `ServiceConvergenceStep` has no branch for `FBOSS_HW_AGENT_0` — passing
    that service to the convergence step is a silent no-op. The gate therefore
    uses `AGENT` (agent-configured) plus `BGP`, extending the `AGENT`-only gate
    that `test_fboss_hw_agent_0_crash` already relies on.

    The restart check monitors only `fboss_hw_agent@0`. Whether a hw_agent
    coldboot also bounces `fboss_sw_agent` is not something the documented
    wedge_agent cascade covers, so keeping the monitored set narrow avoids a
    false failure in either direction.

    Args:
        iteration: Number of coldboot cycles. Default 15.

    Returns:
        A `Playbook` named `test_fboss_hw_agent_0_coldboot`.
    """
    return Playbook(
        name="test_fboss_hw_agent_0_coldboot",
        postchecks=[
            create_ixia_packet_loss_check(clear_traffic_stats=True),
            create_service_restart_health_check(
                ["fboss_hw_agent@0"],
                expected_restarted_services=["fboss_hw_agent@0"],
            ),
        ],
        stages=[
            create_steps_stage(
                iteration=iteration,
                steps=[
                    create_service_interruption_step(
                        service=Service.FBOSS_HW_AGENT_0,
                        trigger=ServiceInterruptionTrigger.SYSTEMCTL_RESTART,
                        create_cold_boot_file=True,
                        description="Coldboot fboss_hw_agent@0",
                    ),
                    create_service_convergence_step(
                        services=[Service.AGENT, Service.BGP],
                        description=(
                            "Wait for the agent and bgpd to converge before the "
                            "next coldboot"
                        ),
                    ),
                ],
            ),
        ],
    )


def _nbr_flap_non_circuit_checks(
    restart_service_check: PointInTimeHealthCheck,
) -> t.List[PointInTimeHealthCheck]:
    """Mid-test health checks for a disruption + neighbour-flap window.

    Circuit-dependent checks are filtered out because the neighbour's uplinks are
    intentionally down for most of the window. IXIA packet loss is excluded for
    the same reason: traffic runs DUT -> STSW -> NBR, so flapping the NBR's
    uplinks breaks the path by design.

    `restart_service_check` must match the service actually being disrupted.
    A check built for one service false-fails another: the agent-warmboot
    variant expects the whole wedge_agent BindsTo cascade to have restarted,
    while the per-service variants instead assert every OTHER service stayed
    up (see `SERVICES_TO_MONITOR_DURING_*_RESTART`).
    """
    return filter_out_circuit_health_checks(
        [
            create_systemctl_active_state_check(),
            create_unclean_exit_check(),
            create_device_core_dumps_check(),
            create_memory_utilization_check(threshold=5 * (1024**3)),
            create_cpu_utilization_check(threshold=400.0),
            restart_service_check,
        ],
        also_exclude={hc_types.CheckName.IXIA_PACKET_LOSS_CHECK},
    )


def _warmboot_nbr_flap_non_circuit_checks() -> t.List[PointInTimeHealthCheck]:
    """Mid-test checks for the agent-warmboot + neighbour-flap window.

    Thin wrapper kept so the landed warmboot playbook's serialized output is
    unchanged by the generalization above.
    """
    return _nbr_flap_non_circuit_checks(AGENT_WARMBOOT_SERVICE_CHECK)


def create_gtsw_warmboot_nbr_uplink_flap_playbook(
    nbr_device_name: str,
    iteration: int = 3,
    nbr_uplink_neighbor_pattern: str = "stsw*",
    per_iteration_flap_sec: int = 200,
    longevity_sec: int = 300,
    playbook_name: str = "test_warmboot_nbr_uplink_flap",
    traffic_items_to_configure: t.Optional[t.Mapping[str, TrafficItemSettings]] = None,
) -> Playbook:
    """Build a `test_warmboot_nbr_uplink_flap` Playbook.

    Exercises a GTSW re-converging while its fabric neighbour's uplinks churn.
    Each pass is:

      1. Warmboot the DUT agent, wait for agent + bgpd convergence, rapid-flap
         the neighbour's STSW-facing uplinks, converge again, then run the
         non-circuit health checks.
      2. A `longevity_sec` steady-state settle.

    `iteration` repeats the whole thing at the PLAYBOOK level, not the stage
    level, so every pass also re-runs the postchecks below and gets a fresh
    `test_case_start_time` window (`libs/taac_runner.py:814`). That matters:
    the time-windowed checks (unclean exit, core dumps, service restart) are
    then scoped to their own pass rather than to the whole run.

    The neighbour is flapped via `create_fpf_rapid_flap_step_lldp` scoped with
    `device_regexes`. That step is wall-clock bounded (its handler loops until
    the deadline) and resolves the uplink set from the neighbour's own LLDP
    table, so no breakout ports are hardcoded. Its sibling
    `create_fpf_rapid_flap_step` derives a flap COUNT from the duration and has
    overshot its window badly in the past — do not substitute it here.

    Health-check placement: the in-pass check is a MID_TEST validation step
    carrying only the non-circuit set, because the links are intentionally
    down. The playbook's own postchecks (the full usual set) are injected as
    the final stage by the runner, so they land after the longevity settle when
    every link is expected back up.

    Args:
        nbr_device_name: Hostname of the non-DUT neighbour to flap.
        iteration: Playbook-level repeats of the whole warmboot + flap +
            longevity + postcheck sequence. Default 3.
        nbr_uplink_neighbor_pattern: fnmatch glob over the neighbour's LLDP
            remote system names selecting which uplinks to flap.
        per_iteration_flap_sec: Flap window within each pass.
        longevity_sec: Steady-state settle before the full postchecks.
        playbook_name: Playbook name, which is also the TAAC test-case name.
            Must be unique when a TestConfig instantiates this factory more
            than once.
        traffic_items_to_configure: Per-playbook traffic overrides, applied by
            the runner in `async_test_case_setUp` before traffic starts
            (`libs/taac_runner.py:1718-1729`). Used to pin a frame size for the
            duration of this playbook. Because the override mutates the live
            IXIA traffic item and every playbook in a TestConfig shares one
            session, a TestConfig running several of these should set it on
            ALL of them — otherwise a playbook that omits it silently inherits
            whatever the previous playbook left configured.

    Returns:
        A `Playbook` named `playbook_name`.
    """
    non_circuit_checks = _warmboot_nbr_flap_non_circuit_checks()

    def _nbr_flap_step(duration_sec: int) -> Step:
        return create_fpf_rapid_flap_step_lldp(
            neighbor_pattern=nbr_uplink_neighbor_pattern,
            duration_sec=duration_sec,
            flap_down_time_sec=6,
            flap_up_time_sec=6,
            device_regexes=[nbr_device_name],
            description=(
                f"Rapid-flap LLDP-resolved uplinks "
                f"(neighbors~={nbr_uplink_neighbor_pattern!r}) on "
                f"{nbr_device_name} for {duration_sec}s (wall-clock bound)"
            ),
        )

    return Playbook(
        name=playbook_name,
        iteration=iteration,
        traffic_items_to_configure=traffic_items_to_configure,
        postchecks=[
            AGENT_WARMBOOT_SERVICE_CHECK,
            create_systemctl_active_state_check(),
            create_device_core_dumps_check(),
            create_unclean_exit_check(),
            create_lldp_check(),
            create_port_state_check(),
            create_packetloss_health_check(),
        ],
        stages=[
            create_steps_stage(
                stage_id="warmboot_nbr_flap",
                steps=[
                    create_service_interruption_step(
                        service=Service.AGENT,
                        trigger=ServiceInterruptionTrigger.SYSTEMCTL_RESTART,
                        description="Warmboot the DUT FBOSS agent",
                    ),
                    create_service_convergence_step(
                        services=[Service.AGENT, Service.BGP],
                        description="Converge after warmboot, before flapping",
                    ),
                    _nbr_flap_step(per_iteration_flap_sec),
                    create_service_convergence_step(
                        services=[Service.AGENT, Service.BGP],
                        description="Converge after the neighbour uplink flap",
                    ),
                    create_validation_step(
                        point_in_time_checks=non_circuit_checks,
                        stage=taac_types.ValidationStage.MID_TEST,
                        description=(
                            "Non-circuit health for this pass "
                            "(links intentionally flapping)"
                        ),
                    ),
                ],
            ),
            create_steps_stage(
                stage_id="longevity",
                steps=[
                    create_longevity_step(
                        duration=longevity_sec,
                        description=(
                            f"Settle {longevity_sec}s before the full "
                            "health-check set"
                        ),
                    ),
                ],
            ),
        ],
    )


def create_gtsw_service_restart_nbr_uplink_flap_playbook(
    nbr_device_name: str,
    playbook_name: str,
    service: Service,
    restart_service_check: PointInTimeHealthCheck,
    convergence_services: t.Sequence[Service],
    service_label: str,
    iteration: int = 3,
    nbr_uplink_neighbor_pattern: str = "stsw*",
    per_iteration_flap_sec: int = 200,
    longevity_sec: int = 300,
    post_restart_settle_sec: int = 0,
    extra_post_flap_checks: t.Optional[t.Sequence[PointInTimeHealthCheck]] = None,
    traffic_items_to_configure: t.Optional[t.Mapping[str, TrafficItemSettings]] = None,
) -> Playbook:
    """Restart one service on the DUT, then flap the neighbour's uplinks.

    Same shape as `create_gtsw_warmboot_nbr_uplink_flap_playbook`, but the
    disruption is a targeted systemctl restart of a single service rather than
    an agent warmboot. Each pass is:

      1. Restart `service`, optionally settle, converge on
         `convergence_services`, rapid-flap the neighbour's STSW-facing
         uplinks, converge again, then run the non-circuit health checks plus
         `extra_post_flap_checks`.
      2. A `longevity_sec` steady-state settle.

    `iteration` repeats the whole thing at the PLAYBOOK level, so every pass
    also re-runs the postchecks and gets a fresh `test_case_start_time` window.

    `restart_service_check` MUST match `service`. The per-service constants
    (`QSFP_SERVICE_RESTART_SERVICE_CHECK` and friends) assert that every OTHER
    service stayed up, which is the meaningful claim for a targeted restart —
    passing the agent-warmboot variant here would instead demand a whole
    cascade of restarts and false-fail.

    `extra_post_flap_checks` run in the same MID_TEST validation step, after
    the post-flap convergence, so they see links restored. That is where
    circuit-dependent assertions belong (port state, BGP session
    establishment); the non-circuit set deliberately filters those out because
    the links are down for most of the window.

    Args:
        nbr_device_name: Hostname of the non-DUT neighbour to flap.
        playbook_name: Playbook name, also the TAAC test-case name.
        service: Service to systemctl-restart on the DUT.
        restart_service_check: Service-restart health check matching `service`.
        convergence_services: Services to wait on after the restart and again
            after the flap.
        service_label: Human-readable service name for step descriptions.
        iteration: Playbook-level repeats. Default 3.
        nbr_uplink_neighbor_pattern: fnmatch glob over the neighbour's LLDP
            remote system names selecting which uplinks to flap.
        per_iteration_flap_sec: Flap window within each pass.
        longevity_sec: Steady-state settle before the full postchecks.
        post_restart_settle_sec: Fixed settle after the restart, before
            convergence. Used for services with no convergence signal.
        extra_post_flap_checks: Extra checks appended to the per-pass
            validation, after the flap has recovered.
        traffic_items_to_configure: Per-playbook traffic overrides. See
            `create_gtsw_warmboot_nbr_uplink_flap_playbook` for why every
            playbook in a shared TestConfig should set this.

    Returns:
        A `Playbook` named `playbook_name`.
    """
    non_circuit_checks = list(_nbr_flap_non_circuit_checks(restart_service_check))
    non_circuit_checks.extend(extra_post_flap_checks or [])

    restart_steps = [
        create_service_interruption_step(
            service=service,
            trigger=ServiceInterruptionTrigger.SYSTEMCTL_RESTART,
            description=f"Restart {service_label} on the DUT",
        ),
    ]
    if post_restart_settle_sec:
        restart_steps.append(
            create_longevity_step(
                duration=post_restart_settle_sec,
                description=(
                    f"Settle {post_restart_settle_sec}s after the "
                    f"{service_label} restart"
                ),
            )
        )

    return Playbook(
        name=playbook_name,
        iteration=iteration,
        traffic_items_to_configure=traffic_items_to_configure,
        postchecks=[
            restart_service_check,
            create_systemctl_active_state_check(),
            create_device_core_dumps_check(),
            create_unclean_exit_check(),
            create_lldp_check(),
            create_port_state_check(),
            create_packetloss_health_check(),
        ],
        stages=[
            create_steps_stage(
                stage_id="service_restart_nbr_flap",
                steps=[
                    *restart_steps,
                    create_service_convergence_step(
                        services=list(convergence_services),
                        description=(
                            f"Converge after the {service_label} restart, "
                            "before flapping"
                        ),
                    ),
                    create_fpf_rapid_flap_step_lldp(
                        neighbor_pattern=nbr_uplink_neighbor_pattern,
                        duration_sec=per_iteration_flap_sec,
                        flap_down_time_sec=6,
                        flap_up_time_sec=6,
                        device_regexes=[nbr_device_name],
                        description=(
                            f"Rapid-flap LLDP-resolved uplinks "
                            f"(neighbors~={nbr_uplink_neighbor_pattern!r}) on "
                            f"{nbr_device_name} for {per_iteration_flap_sec}s "
                            "(wall-clock bound)"
                        ),
                    ),
                    create_service_convergence_step(
                        services=list(convergence_services),
                        description="Converge after the neighbour uplink flap",
                    ),
                    create_validation_step(
                        point_in_time_checks=non_circuit_checks,
                        stage=taac_types.ValidationStage.MID_TEST,
                        description=(
                            "Non-circuit health for this pass, plus any "
                            "post-flap circuit checks (links recovered)"
                        ),
                    ),
                ],
            ),
            create_steps_stage(
                stage_id="longevity",
                steps=[
                    create_longevity_step(
                        duration=longevity_sec,
                        description=(
                            f"Settle {longevity_sec}s before the full "
                            "health-check set"
                        ),
                    ),
                ],
            ),
        ],
    )


def create_fsdb_crash_playbook(iteration: int = 5) -> Playbook:
    """Build the `test_fsdb_crash` Playbook.

    Repeats `iteration` cycles of crashing fsdb followed by a 10s
    longevity settle. Pre/postchecks exclude `fsdb` from the
    unclean-exit ledger.

    Args:
        iteration: Number of crash cycles. Default 5.

    Returns:
        A `Playbook` named `test_fsdb_crash`.
    """
    return Playbook(
        name="test_fsdb_crash",
        prechecks=[
            _unclean_exit_check(["fsdb"]),
        ],
        postchecks=[
            FSDB_RESTART_SERVICE_CHECK,
            _unclean_exit_check(["fsdb"]),
        ],
        stages=[
            create_steps_stage(
                iteration=iteration,
                steps=[
                    create_service_interruption_step(
                        service=Service.FSDB,
                        trigger=ServiceInterruptionTrigger.CRASH,
                    ),
                    create_longevity_step(duration=10),
                ],
            ),
        ],
    )


TEST_WEDGE_AGENT_AND_FSDB_CRASH_PLAYBOOK = Playbook(
    name="test_wedge_agent_and_fsdb_crash",
    prechecks=[
        create_systemctl_active_state_check(),
        create_wedge_agent_configured_check(),
    ],
    postchecks=[create_ixia_packet_loss_check(clear_traffic_stats=True)],
    stages=[
        create_steps_stage(
            steps=[
                create_service_interruption_step(
                    service=Service.AGENT,
                    trigger=ServiceInterruptionTrigger.CRASH,
                ),
                create_service_interruption_step(
                    service=Service.FSDB,
                    trigger=ServiceInterruptionTrigger.CRASH,
                ),
            ],
            concurrent=True,
        ),
        create_steps_stage(
            steps=[
                create_service_convergence_step(services=[Service.AGENT, Service.FSDB]),
                create_longevity_step(duration=180),
            ],
        ),
    ],
)


