def create_w400_interface_flap_playbook(
    interfaces: t.List[str],
    device_name: str,
    packet_loss_check_clear_stats: PointInTimeHealthCheck,
    packet_loss_check: PointInTimeHealthCheck,
    systemctl_check: PointInTimeHealthCheck,
    traffic_items_to_start: t.List[str],
    snapshot_checks: t.List[SnapshotHealthCheck],
) -> Playbook:
    return Playbook(
        name="test_w400_ash6_interface_flap",
        prechecks=[systemctl_check, packet_loss_check],
        stages=[
            create_steps_stage(
                steps=[
                    create_interface_flap_step(
                        enable=False,
                        interfaces=interfaces,
                        device_name=device_name,
                        interface_flap_method=4,
                        delay=10,
                    ),
                    create_interface_flap_step(
                        enable=True,
                        interfaces=interfaces,
                        device_name=device_name,
                        interface_flap_method=4,
                        delay=30,
                    ),
                    create_interface_flap_step(
                        enable=False,
                        interfaces=interfaces,
                        device_name=device_name,
                        interface_flap_method=4,
                        delay=10,
                    ),
                    create_interface_flap_step(
                        enable=True,
                        interfaces=interfaces,
                        device_name=device_name,
                        interface_flap_method=4,
                        delay=30,
                    ),
                    create_service_convergence_step(
                        services=[taac_types.Service.AGENT, taac_types.Service.BGP],
                    ),
                    create_longevity_step(duration=60),
                ]
            )
        ],
        postchecks=[packet_loss_check_clear_stats, systemctl_check],
        traffic_items_to_start=traffic_items_to_start,
        enabled=True,
        snapshot_checks=snapshot_checks,
    )


def create_fpf_prefix_injection_stress_playbook(
    gtsws: list[str],
    hosts: list[str],
    trigger_stsws: list[str],
    baseline_delay_sec: int = 120,
    collection_duration_sec: int = 720,
    poll_interval_sec: int = 5,
    subnet_prefix: str = "5000:dd::/32",
    prefix_count: int = 20000,
    community_list: str = "stsw",
    lanes: list[int] | None = None,
    services_to_check: list[str] | None = None,
) -> Playbook:
    """Full FPF prefix-injection stress playbook (prechecks + stress stage + postchecks).

    Wraps `create_fpf_stress_concurrent_stage` with standard FPF pre/postchecks
    and a withdraw cleanup step.
    """
    from taac.health_checks.healthcheck_definitions import (
        create_bgp_rib_fib_consistency_check,
        create_bgp_session_establish_check,
        create_core_dumps_snapshot_check,
        create_device_core_dumps_check,
        create_fpf_bgp_rib_convergence_check,
        create_fpf_fsdb_ribmap_convergence_check,
        create_fpf_hrt_bulk_convergence_check,
        create_fpf_hrt_fsdb_session_check,
        create_fpf_stale_prefix_check,
        create_memory_utilization_check,
        create_port_state_check,
        create_systemctl_active_state_check,
        create_unclean_exit_check,
    )
    from taac.stages.stage_definitions import (
        create_fpf_stress_concurrent_stage,
    )
    from taac.steps.step_definitions import (
        create_fpf_bgp_prefix_injection_step,
    )

    services = services_to_check or ["bgpd", "fsdb", "wedge_agent", "qsfp_service"]
    resolved_lanes = lanes if lanes is not None else [0, 1]

    prechecks = [
        create_bgp_session_establish_check(),
        create_port_state_check(),
        create_systemctl_active_state_check(services_json=services),
        create_unclean_exit_check(),
        create_device_core_dumps_check(),
        create_fpf_stale_prefix_check(
            subnet_prefix=subnet_prefix,
            check_id="fpf_stale_prefix_precheck",
        ),
        create_fpf_hrt_fsdb_session_check(
            hosts=hosts,
            check_id="fpf_hrt_precheck",
        ),
    ]

    convergence_postchecks = []
    for lane_id, gtsw in enumerate(gtsws):
        lane_map = {str(lane_id): gtsw}
        convergence_postchecks.append(
            create_fpf_fsdb_ribmap_convergence_check(
                lane_map=lane_map,
                expected_matched=prefix_count,
                trigger_delay_sec=baseline_delay_sec,
                check_id=f"fpf_fsdb_convergence_lane{lane_id}",
            )
        )
        convergence_postchecks.append(
            create_fpf_bgp_rib_convergence_check(
                lane_map=lane_map,
                expected_matched=prefix_count,
                trigger_delay_sec=baseline_delay_sec,
                check_id=f"fpf_bgp_convergence_lane{lane_id}",
            )
        )
    for lane_id in resolved_lanes:
        convergence_postchecks.append(
            create_fpf_hrt_bulk_convergence_check(
                lanes=[lane_id],
                expected_per_lane={str(lane_id): prefix_count},
                trigger_delay_sec=baseline_delay_sec,
                check_id=f"fpf_hrt_convergence_lane{lane_id}",
            )
        )

    postchecks = [
        create_bgp_session_establish_check(),
        create_port_state_check(),
        create_systemctl_active_state_check(services_json=services),
        create_unclean_exit_check(),
        create_device_core_dumps_check(),
        create_bgp_rib_fib_consistency_check(),
        create_memory_utilization_check(),
        create_fpf_hrt_fsdb_session_check(
            hosts=hosts,
            check_id="fpf_hrt_postcheck",
        ),
        *convergence_postchecks,
    ]

    snapshot_checks = [create_core_dumps_snapshot_check()]

    stress_stage = create_fpf_stress_concurrent_stage(
        gtsws=gtsws,
        hosts=hosts,
        trigger_stsws=trigger_stsws,
        baseline_delay_sec=baseline_delay_sec,
        collection_duration_sec=collection_duration_sec,
        poll_interval_sec=poll_interval_sec,
        subnet_prefix=subnet_prefix,
        prefix_count=prefix_count,
        community_list=community_list,
        lanes=resolved_lanes,
    )

    cleanup_steps = [
        create_fpf_bgp_prefix_injection_step(
            devices=trigger_stsws,
            count=prefix_count,
            community_list=community_list,
            withdraw_only=True,
            description="Withdraw injected BGP prefixes (cleanup)",
        ),
    ]

    return Playbook(
        name="fpf_prefix_injection_stress",
        prechecks=prechecks,
        postchecks=postchecks,
        snapshot_checks=snapshot_checks,
        stages=[stress_stage],
        cleanup_steps=cleanup_steps,
    )


def _build_fpf_generic_checks(
    *,
    hosts: list[str],
    services: list[str],
    gtsws: list[str],
    trigger_stsws: list[str],
    skip_ssh_dependent_checks: bool,
    fsdb_sessions_per_host: int | None,
    prod_prefixes: list[str] | None,
    hrt_memory_hosts: list[str] | None,
    hrt_driver_hosts: list[str] | None,
    spray_hosts: list[str] | None,
    ods_entities: list[str] | None,
    use_bgp_snapshot: bool = False,
    skip_fsdb_session_precheck: bool = False,
    skip_fsdb_session_postcheck: bool = False,
    skip_port_state_precheck: bool = False,
    ods_discard_informational: bool = False,
    host_spray_label: str = "",
    host_spray_excluded_lanes_by_host: dict[str, list[str]] | None = None,
    spray_impacted_by_host: dict | None = None,
    spray_impacted_max_gbps: float | None = None,
    spray_excluded_by_host: dict | None = None,
    assert_bgp_reconvergence: bool = False,
    reconvergence_service: str = "bgpd",
    reconvergence_sla_sec: float = 60.0,
    reconvergence_hosts: list[str] | None = None,
    out_congestion_last_minute_max: bool = False,
    host_spray_transform_desc: str | None = None,
    hrt_device_ids: list[int] | None = None,
) -> tuple[list, list, list]:
    """Build the generic (non-convergence) FPF check lists shared by the
    hardening / service-restart playbooks.

    Returns ``(generic_prechecks, generic_postchecks, snapshot_checks)``.

    This is the generic-check logic factored out of
    ``create_fpf_hardening_playbook_v2`` verbatim so every caller produces the
    same generic check set (and v2's assembled lists stay byte-for-byte
    identical). It deliberately does NOT include the convergence checks, the
    prod-prefix-stability postcheck, the HRT plane-status postcheck, or the
    BGP convergence-timing disruption postcheck — those stay in each caller.

    ``generic_postchecks`` is ordered as the SSH/device-shell "head" block
    (bgp-establish, port-state, systemctl, unclean-exit, device-core-dumps,
    bgp-rib-fib-consistency, mem-util, cpu-util, hrt-fsdb-session) followed by
    the ODS-only "tail" block (ODS discard/congestion counters, HRT
    system-memory, HRT driver-disconnect, host-spray). Callers that need to
    splice convergence checks between the two blocks (v2) can split on the
    first ODS check (``ods_in_dst_null_discard``); callers that don't (v1,
    service-restart) use the flat list directly.

    When ``skip_ssh_dependent_checks`` is set, the SSH/device-shell generic
    checks AND the ODS discard/congestion counters are dropped, but the
    ODS-only HRT-mem / HRT-driver / host-spray and the prod-prefix / HRT-mem /
    HRT-driver prechecks are KEPT (they only need ODS/collector access).

    ``spray_impacted_by_host`` (host -> ["beth0", ...]) + ``spray_impacted_max_gbps``
    POSITIVELY assert those NIC lanes are drained (egress < the max) on the
    host-spray check while the floor/spread are asserted only over the remaining
    (genuinely unimpacted) lanes. Both default to None -> the host-spray check is
    built exactly as before (byte-identical for callers that pass neither).
    """
    from taac.health_checks.healthcheck_definitions import (
        create_bgp_session_establish_check,
        create_bgp_session_snapshot_check,
        create_core_dumps_snapshot_check,
        create_device_core_dumps_check,
        create_fpf_host_spray_check,
        create_fpf_hrt_driver_disconnect_check,
        create_fpf_hrt_fsdb_session_check,
        create_fpf_hrt_system_memory_check,
        create_fpf_ods_counter_check,
        create_fpf_prod_hrt_prefix_stability_check,
        create_memory_utilization_check,
        create_port_state_check,
        create_systemctl_active_state_check,
        create_unclean_exit_check,
    )

    from taac.libs.fpf.fpf_thresholds import (
        ACTIVE as FPF_ACTIVE_THRESHOLDS,
    )

    # --- Prechecks -------------------------------------------------------
    prechecks = (
        []
        if skip_ssh_dependent_checks
        else [
            *(
                []
                if use_bgp_snapshot
                else [create_bgp_session_establish_check(min_established_pct=0.5)]
            ),
            # Port-state precheck. Skipped on a restore half that re-enables ports
            # in-stage (skip_port_state_precheck): the preceding disrupt left the
            # impacted uplinks DOWN, so a precheck (which runs before the re-enable
            # step) would see the still-/just-re-enabled ports un-settled and FAIL.
            # The postcheck re-asserts full port/plane recovery after the settle.
            *([] if skip_port_state_precheck else [create_port_state_check()]),
            create_systemctl_active_state_check(services_json=services),
            create_unclean_exit_check(),
            create_device_core_dumps_check(),
            *(
                []
                if skip_fsdb_session_precheck
                else [
                    create_fpf_hrt_fsdb_session_check(
                        hosts=hosts,
                        expected_session_count=fsdb_sessions_per_host,
                        device_ids=(
                            hrt_device_ids if hrt_device_ids != [0] else None
                        ),
                        planes_per_device=(
                            4 if hrt_device_ids and hrt_device_ids != [0] else None
                        ),
                        check_id="fpf_hrt_precheck",
                    )
                ]
            ),
        ]
    )
    # ODS/collector baseline prechecks (no SSH needed): kept in both modes.
    if prod_prefixes:
        prechecks.append(
            create_fpf_prod_hrt_prefix_stability_check(
                check_id="fpf_prod_hrt_prefix_stability_precheck",
            )
        )
    if hrt_memory_hosts:
        prechecks.append(
            create_fpf_hrt_system_memory_check(
                hosts=hrt_memory_hosts,
                threshold_gib=FPF_ACTIVE_THRESHOLDS.hrt_system_memory_max_gib,
                check_id="fpf_hrt_system_memory_precheck",
            )
        )
    if hrt_driver_hosts:
        prechecks.append(
            create_fpf_hrt_driver_disconnect_check(
                hosts=hrt_driver_hosts,
                check_id="fpf_hrt_driver_disconnect_precheck",
            )
        )

    # --- ODS discard/congestion counter postchecks (SSH-independent but
    # dropped in minimal mode alongside the generic SSH checks). ---
    # The two non-congestion discard counters use a per-entity pre-test
    # ``.sum.60`` ceiling. The configured 10k threshold is additional events per
    # minute, not an absolute total. ``ods_discard_informational`` permits only a
    # transient excess during disruptive tests; final recovery remains hard.
    # Congestion counters always retain their absolute-zero hard contract.
    # ODS discard/congestion checks scoped to the observer GTSWs only — STSWs are
    # deliberately not monitored (matches create_fpf_endpoints excluding STSWs from
    # per-device checks). Callers can still pass explicit ods_entities to override.
    ods_entity_desc = ",".join(ods_entities or gtsws)
    ods_reduce = r"groupby(entity, (\S+?\.\S+?)\..*, %1),sum"
    ods_postchecks = [
        create_fpf_ods_counter_check(
            entity_desc=ods_entity_desc,
            key_desc="regex(fboss.agent.eth.*discards.sum.60),filter(.*in_dst_null.*)",
            validation_expr=f"<= {FPF_ACTIVE_THRESHOLDS.ods_in_dst_null_discard_max}",
            reduce_desc=ods_reduce,
            counter_name="in_dst_null_discard",
            shorten_pass_url=True,
            baseline_excess_max=FPF_ACTIVE_THRESHOLDS.ods_in_dst_null_discard_max,
            transient_excess_informational=ods_discard_informational,
            check_id="ods_in_dst_null_discard",
        ),
        create_fpf_ods_counter_check(
            entity_desc=ods_entity_desc,
            key_desc="regex(fboss.agent.eth.*discards.sum.60),filter(.*in_discard.*)",
            validation_expr=f"<= {FPF_ACTIVE_THRESHOLDS.ods_in_discard_max}",
            reduce_desc=ods_reduce,
            counter_name="in_discard",
            shorten_pass_url=True,
            baseline_excess_max=FPF_ACTIVE_THRESHOLDS.ods_in_discard_max,
            transient_excess_informational=ods_discard_informational,
            check_id="ods_in_discard",
        ),
        create_fpf_ods_counter_check(
            entity_desc=ods_entity_desc,
            key_desc="regex(fboss.agent.eth.*congestion.*sum.60),filter(.*in_congestion_discards.sum.*)",
            validation_expr=f"<= {FPF_ACTIVE_THRESHOLDS.ods_in_congestion_max}",
            reduce_desc=ods_reduce,
            counter_name="in_congestion",
            shorten_pass_url=True,
            check_id="ods_in_congestion",
        ),
        create_fpf_ods_counter_check(
            entity_desc=ods_entity_desc,
            key_desc="regex(fboss.agent.eth.*congestion.*sum.60),filter(.*out_congestion_discards.sum.*)",
            validation_expr=f"<= {FPF_ACTIVE_THRESHOLDS.ods_out_congestion_max}",
            reduce_desc=ods_reduce,
            counter_name="out_congestion",
            shorten_pass_url=True,
            aggregate="max" if out_congestion_last_minute_max else None,
            require="all" if out_congestion_last_minute_max else "all",
            use_test_case_start_time=not out_congestion_last_minute_max,
            min_ods_query_duration=60 if out_congestion_last_minute_max else 0,
            check_id="ods_out_congestion",
        ),
    ]

    # HRT system-memory / driver-disconnect / host-spray postchecks (ODS-only,
    # kept in both minimal and full modes).
    hrt_memory_postchecks = []
    if hrt_memory_hosts:
        hrt_memory_postchecks.append(
            create_fpf_hrt_system_memory_check(
                hosts=hrt_memory_hosts,
                threshold_gib=FPF_ACTIVE_THRESHOLDS.hrt_system_memory_max_gib,
                check_id="fpf_hrt_system_memory",
            )
        )
    hrt_driver_postchecks = []
    if hrt_driver_hosts:
        hrt_driver_postchecks.append(
            create_fpf_hrt_driver_disconnect_check(
                hosts=hrt_driver_hosts,
                check_id="fpf_hrt_driver_disconnect",
            )
        )
    spray_postchecks = []
    if spray_hosts:
        spray_postchecks.append(
            create_fpf_host_spray_check(
                hosts=spray_hosts,
                min_egress_gbps=FPF_ACTIVE_THRESHOLDS.host_spray_min_egress_gbps,
                max_spread_gbps=FPF_ACTIVE_THRESHOLDS.host_spray_max_spread_gbps,
                # Drain contract: the impacted NIC lanes (e.g. beth0) are asserted
                # ~0 (egress < spray_impacted_max_gbps) while the floor/spread are
                # judged only over the remaining lanes. None for both => unchanged.
                impacted_lanes_by_host=spray_impacted_by_host or None,
                impacted_max_gbps=(
                    spray_impacted_max_gbps if spray_impacted_by_host else None
                ),
                # Excluded/recovering lanes are dropped from floor+spread entirely
                # (NOT asserted drained). Two callers feed this: the STSW-drain
                # ``host_spray_excluded_lanes_by_host`` and the GR-beyond/kill
                # ``spray_excluded_by_host`` (disrupted lane that re-ramps). Only one
                # is set per call. None for both => unchanged.
                excluded_lanes_by_host=(
                    host_spray_excluded_lanes_by_host or spray_excluded_by_host or None
                ),
                label=host_spray_label or None,
                transform_desc=host_spray_transform_desc,
                check_id="fpf_host_spray",
            )
        )

    # --- Postchecks + snapshots ------------------------------------------
    if skip_ssh_dependent_checks:
        # Minimal mode: drop the generic SSH checks and ODS counters; keep the
        # ODS-only HRT-mem / HRT-driver / host-spray postchecks.
        generic_postchecks = [
            *hrt_memory_postchecks,
            *hrt_driver_postchecks,
            *spray_postchecks,
        ]
        snapshot_checks = []
    else:
        generic_postchecks = [
            # head: SSH/device-shell generic checks
            *(
                []
                if use_bgp_snapshot
                else [create_bgp_session_establish_check(min_established_pct=0.5)]
            ),
            create_port_state_check(),
            create_systemctl_active_state_check(services_json=services),
            create_unclean_exit_check(),
            create_device_core_dumps_check(),
            # BGP RIB<->FIB consistency check omitted: it is FBOSS-OS-gated and
            # SKIPs (empty message) on these MWG2 GTSW/STSW endpoints, validating
            # nothing while inflating the per-host SKIP-counted-as-failed tally.
            create_memory_utilization_check(
                threshold=FPF_ACTIVE_THRESHOLDS.mem_util_default_bytes,
                threshold_by_service=dict(FPF_ACTIVE_THRESHOLDS.mem_util_by_service),
                start_time_jq_var="test_case_start_time",
            ),
            # HRT FSDB-session POSTcheck. Skipped for fsdb/bgp GR-style configs:
            # fsdb and HRT are coupled, so a brief HRT FSDB-session census dip is
            # EXPECTED while fsdb (or the GR'd process) re-subscribes — not a fault.
            # The precheck still asserts a healthy 32/32 baseline.
            *(
                []
                if skip_fsdb_session_postcheck
                else [
                    create_fpf_hrt_fsdb_session_check(
                        hosts=hosts,
                        expected_session_count=fsdb_sessions_per_host,
                        device_ids=(
                            hrt_device_ids if hrt_device_ids != [0] else None
                        ),
                        planes_per_device=(
                            4 if hrt_device_ids and hrt_device_ids != [0] else None
                        ),
                        check_id="fpf_hrt_postcheck",
                    )
                ]
            ),
            # tail: ODS-only checks
            *ods_postchecks,
            *hrt_memory_postchecks,
            *hrt_driver_postchecks,
            *spray_postchecks,
        ]
        snapshot_checks = [
            create_core_dumps_snapshot_check(),
        ]
        if use_bgp_snapshot:
            snapshot_checks.append(
                create_bgp_session_snapshot_check(
                    skip_flap_check=True, skip_uptime_check=True
                )
            )

    # Reconvergence-timing snapshot (opt-in, process-disruption configs only):
    # assert every peer Established before the playbook re-established within the
    # SLA of the disrupted service's restart, scoped to the disrupted device.
    # Needs SSH (systemctl ActiveEnterTimestamp + BGP session query), so it is
    # not added in skip_ssh_dependent_checks (minimal) mode.
    if assert_bgp_reconvergence and not skip_ssh_dependent_checks:
        snapshot_checks.append(
            create_bgp_session_snapshot_check(
                skip_flap_check=True,
                skip_uptime_check=True,
                assert_reconvergence=True,
                max_convergence_sec=reconvergence_sla_sec,
                convergence_service=reconvergence_service,
                reconvergence_hosts=reconvergence_hosts,
            )
        )

    return prechecks, generic_postchecks, snapshot_checks


# Number of ODS-only "tail" postchecks the generic builder appends after the
# SSH/device-shell "head" block, given the ODS-only host lists. v2 uses this to
# splice its convergence checks between the head and the tail so its assembled
# postcheck order stays byte-for-byte identical.
def _fpf_generic_postcheck_tail_len(
    *,
    skip_ssh_dependent_checks: bool,
    hrt_memory_hosts: list[str] | None,
    hrt_driver_hosts: list[str] | None,
    spray_hosts: list[str] | None,
) -> int:
    n = 1 if hrt_memory_hosts else 0
    n += 1 if hrt_driver_hosts else 0
    n += 1 if spray_hosts else 0
    if not skip_ssh_dependent_checks:
        n += 4  # the four ODS discard/congestion counter checks
    return n


def create_fpf_hardening_playbook(
    gtsws: list[str],
    hosts: list[str],
    trigger_stsws: list[str],
    disruption_steps: list,
    disruption_duration_sec: int,
    recovery_wait_sec: int = 300,
    stabilization_delay_sec: int = 600,
    baseline_delay_sec: int = 120,
    injection_estimate_sec: int = 120,
    poll_interval_sec: int = 5,
    subnet_prefix: str = "5000:dd::/32",
    prefix_count: int = 70000,
    community_list: str = "stsw",
    lanes: list[int] | None = None,
    services_to_check: list[str] | None = None,
    additional_postchecks: list | None = None,
    concurrent_disruption_steps: list | None = None,
    playbook_name: str = "fpf_hardening",
    skip_ssh_dependent_checks: bool = False,
    prod_prefixes: list[str] | None = None,
    hrt_memory_hosts: list[str] | None = None,
    hrt_driver_hosts: list[str] | None = None,
    spray_hosts: list[str] | None = None,
    ods_entities: list[str] | None = None,
) -> Playbook:
    """FPF hardening playbook: prefix injection + stabilization + disruptive event.

    Extends the stable-state stress playbook with a disruptive event phase.
    The collector runs continuously through injection, stabilization, disruption,
    and recovery. The playbook structure is:

        prechecks → hardening_concurrent_stage → postchecks → cleanup

    The concurrent stage has 3 tracks (4 if concurrent_disruption_steps provided):
        Track 1: Continuous collector (FSDB ribMap, HRT bulk, BGP RIB)
        Track 2: Baseline delay → prefix injection
        Track 3: Pre-disruption delay → disruption_steps
        Track 4 (optional): Pre-disruption delay → concurrent_disruption_steps
    """
    from taac.health_checks.healthcheck_definitions import (
        create_bgp_stale_route_check,
        create_drain_state_check,
        create_fpf_bgp_rib_convergence_check,
        create_fpf_fsdb_ribmap_convergence_check,
        create_fpf_hrt_bulk_convergence_check,
        create_fpf_hrt_remote_failure_convergence_check,
        create_fpf_stale_prefix_check,
        create_service_restart_check,
    )
    from taac.stages.stage_definitions import (
        create_fpf_hardening_concurrent_stage,
    )
    from taac.steps.step_definitions import (
        create_fpf_bgp_prefix_injection_step,
    )

    services = services_to_check or ["bgpd", "fsdb", "wedge_agent", "qsfp_service"]
    resolved_lanes = lanes if lanes is not None else [0, 1]

    # Track 2 does: baseline_delay → injection (~injection_estimate_sec).
    # Track 3 must wait for injection to finish PLUS a full stabilization
    # window so prefixes are programmed before any disruption starts.
    pre_disruption_delay_sec = (
        baseline_delay_sec + injection_estimate_sec + stabilization_delay_sec
    )

    # Generic (non-convergence) checks shared with v2 / service-restart. This
    # adds the previously-missing ODS-counter / HRT-mem / HRT-driver / host-spray
    # checks plus the skip_ssh gating that v1 lacked.
    generic_prechecks, generic_postchecks, snapshot_checks = _build_fpf_generic_checks(
        hosts=hosts,
        services=services,
        gtsws=gtsws,
        trigger_stsws=trigger_stsws,
        skip_ssh_dependent_checks=skip_ssh_dependent_checks,
        fsdb_sessions_per_host=None,
        prod_prefixes=prod_prefixes,
        hrt_memory_hosts=hrt_memory_hosts,
        hrt_driver_hosts=hrt_driver_hosts,
        spray_hosts=spray_hosts,
        ods_entities=ods_entities,
    )

    # MANDATORY FPF drain pre-check: abort if any in-scope GTSW / trigger STSW is
    # drained (VF routes may already be withdrawn). Drainer doesn't yet support
    # GTSW (T263331198); the check reads the device drain state directly. One
    # check per device since create_drain_state_check is single-device scoped.
    drain_prechecks = [
        create_drain_state_check(expected_drained=False, device_name=device)
        for device in [*gtsws, *trigger_stsws]
    ]

    prechecks = [
        *drain_prechecks,
        *generic_prechecks,
        create_fpf_stale_prefix_check(
            subnet_prefix=subnet_prefix,
            check_id="fpf_stale_prefix_precheck",
        ),
    ]

    convergence_postchecks = []
    for lane_id, gtsw in enumerate(gtsws):
        lane_map = {str(lane_id): gtsw}
        convergence_postchecks.append(
            create_fpf_fsdb_ribmap_convergence_check(
                lane_map=lane_map,
                expected_matched=prefix_count,
                trigger_delay_sec=baseline_delay_sec,
                check_id=f"fpf_fsdb_convergence_lane{lane_id}",
            )
        )
        convergence_postchecks.append(
            create_fpf_bgp_rib_convergence_check(
                lane_map=lane_map,
                expected_matched=prefix_count,
                trigger_delay_sec=baseline_delay_sec,
                check_id=f"fpf_bgp_convergence_lane{lane_id}",
            )
        )
    for lane_id in resolved_lanes:
        convergence_postchecks.append(
            create_fpf_hrt_bulk_convergence_check(
                lanes=[lane_id],
                expected_per_lane={str(lane_id): prefix_count},
                trigger_delay_sec=baseline_delay_sec,
                check_id=f"fpf_hrt_convergence_lane{lane_id}",
            )
        )
    convergence_postchecks.append(
        create_fpf_hrt_remote_failure_convergence_check(
            lanes=resolved_lanes,
            direction="stable",
            use_live_collectors=True,
            check_id="fpf_remote_failure_stable",
        )
    )

    # Process-restart composition (the hardening playbook covers GR/warmboot of
    # various services): assert ONLY the expected services restarted and that no
    # BGP graceful-restart stale routes linger after recovery.
    # SERVICE_RESTART_CHECK is SSH/systemctl-based — gate it behind
    # skip_ssh_dependent_checks; BGP_STALE_ROUTE_CHECK reads the RIB over thrift
    # so it runs in both modes.
    postchecks = [
        *generic_postchecks,
        *(
            []
            if skip_ssh_dependent_checks
            else [create_service_restart_check(services=services)]
        ),
        create_bgp_stale_route_check(),
        *convergence_postchecks,
        *(additional_postchecks or []),
    ]

    hardening_stage = create_fpf_hardening_concurrent_stage(
        gtsws=gtsws,
        hosts=hosts,
        trigger_stsws=trigger_stsws,
        disruption_steps=disruption_steps,
        pre_disruption_delay_sec=pre_disruption_delay_sec,
        disruption_duration_sec=disruption_duration_sec,
        recovery_wait_sec=recovery_wait_sec,
        baseline_delay_sec=baseline_delay_sec,
        poll_interval_sec=poll_interval_sec,
        subnet_prefix=subnet_prefix,
        prefix_count=prefix_count,
        community_list=community_list,
        lanes=resolved_lanes,
        concurrent_disruption_steps=concurrent_disruption_steps,
    )

    cleanup_steps = [
        create_fpf_bgp_prefix_injection_step(
            devices=trigger_stsws,
            count=prefix_count,
            community_list=community_list,
            withdraw_only=True,
            description="Withdraw injected BGP prefixes (cleanup)",
        ),
    ]

    return Playbook(
        name=playbook_name,
        prechecks=prechecks,
        postchecks=postchecks,
        snapshot_checks=snapshot_checks,
        stages=[hardening_stage],
        cleanup_steps=cleanup_steps,
    )


def _fpf_rf_stable_scope(
    group: dict,
    eligible_lanes: t.Iterable[int],
) -> tuple[list[int], dict[str, int]]:
    """Return lanes and expected counts for a per-VF stable RF assertion."""
    eligible = set(eligible_lanes)
    lanes = sorted(int(lane) for lane in group["lanes"] if lane in eligible)
    return lanes, {}


def _fpf_global_lanes_to_hrt_tuples(
    hosts: t.Iterable[str],
    global_lanes: t.Iterable[int],
    device_ids: t.Iterable[int],
    gpu_ids: t.Iterable[int] | None = None,
) -> dict[str, dict[str, list[int]]]:
    """Map physical GPU/global lanes to new-SDK device/local-plane tuples."""
    allowed_devices = {int(device_id) for device_id in device_ids}
    per_host: dict[str, dict[str, list[int]]] = {}
    for host in hosts:
        for gpu_id in gpu_ids or range(4):
            for global_lane in global_lanes:
                device_id = 2 * int(gpu_id) + int(global_lane) // 4
                if device_id not in allowed_devices:
                    continue
                local_plane = int(global_lane) % 4
                planes = per_host.setdefault(host, {}).setdefault(
                    str(device_id), []
                )
                if local_plane not in planes:
                    planes.append(local_plane)
    return per_host


def create_fpf_hardening_playbook_v2(
    gtsws: list[str],
    hosts: list[str],
    trigger_stsws: list[str],
    disruption_steps: list | None = None,
    soak_duration_sec: int = 60,
    stabilization_delay_sec: int = 600,
    prefix_count: int = 70000,
    community_list: str = "stsw",
    lanes: list[int] | None = None,
    services_to_check: list[str] | None = None,
    additional_postchecks: list | None = None,
    ods_entities: list[str] | None = None,
    playbook_name: str = "fpf_hardening_v2",
    prod_prefixes: list[str] | None = None,
    skip_ssh_dependent_checks: bool = False,
    use_bgp_snapshot: bool = False,
    prod_prefix_settle_sec: int = 0,
    convergence_settle_sec: int = 0,
    fsdb_expected_total: int | None = None,
    skip_fsdb_session_precheck: bool = False,
    skip_fsdb_session_postcheck: bool = False,
    skip_port_state_precheck: bool = False,
    hrt_memory_hosts: list[str] | None = None,
    hrt_driver_hosts: list[str] | None = None,
    spray_hosts: list[str] | None = None,
    host_spray_label: str = "",
    host_spray_excluded_lanes_by_host: dict[str, list[str]] | None = None,
    plane_status_check: bool = False,
    prod_prefix_recovery: bool = False,
    local_prod_prefixes: list[str] | None = None,
    impacted_planes_by_host: dict | None = None,
    impacted_lanes_drained: list[int] | None = None,
    impacted_spray_max_gbps: float = 10.0,
    spray_recovering_by_host: dict | None = None,
    skip_injection: bool = False,
    rf_vf_groups: list | None = None,
    restart_ib_traffic_server: str | None = None,
    restart_ib_traffic_clients: list[str] | None = None,
    ib_traffic_config: t.Mapping[str, t.Any] | None = None,
    assert_bgp_reconvergence: bool = False,
    reconvergence_service: str = "bgpd",
    reconvergence_sla_sec: float = 60.0,
    reconvergence_hosts: list[str] | None = None,
    bgp_rib_restart_reconverge: bool = False,
    fsdb_rib_restart_reconverge: bool = False,
    remote_failure_last_sample: bool = False,
    convergence_blip_mode: str = "strict",
    ods_discard_informational: bool = False,
    out_congestion_last_minute_max: bool = False,
    host_spray_transform_desc: str | None = None,
    remote_failure_last_n: bool = False,
    recovery_last_n: int | None = None,
    prod_prefix_restart_recovery_sla_sec: float | None = None,
    hrt_restart_tolerant_hosts: list[str] | None = None,
    hrt_device_ids: list[int] | None = None,
    cleanup_steps: list | None = None,
) -> Playbook:
    """FPF hardening playbook for use with long-lived collectors.

    ``convergence_blip_mode`` selects the two-mode "blip handling" contract for
    ALL convergence (BGP RIB / FSDB ribMap / HRT bulk Signal-3), HRT
    remote-failure, and prod-prefix stability checks this playbook builds:

      "strict" (default) — unchanged; every sample must hold at the golden value
        (byte-identical to before for untouched callers).
      "last_sample" (MODE A, DISRUPTIVE triggers: kill / agent coldboot / reboot
        / GR-beyond / GR-out) — only the LAST in-window sample must equal the
        golden value; mid-window failure values are tolerated.
      "skip_null_strict" (MODE B, GRACEFUL within-window triggers: GR / GR-in for
        fsdb/bgp/wedge_agent) — tolerate null/missing samples (collection blips)
        but every non-null sample (and the last) must equal the golden value.

    It supersedes ``remote_failure_last_sample`` for the remote-failure check
    (when ``convergence_blip_mode != "strict"`` the remote-failure direction is
    derived from it: "last_sample"->stable_last_sample, "skip_null_strict"->
    stable_skip_null_strict).

    ``rf_vf_groups`` (8-STSW split-per-VF injection): list of
    ``{"suffix", "subnet", "lanes"}``. When given, the single broad HRT
    remote-failure "stable" check is replaced by one per VF group, each reading
    its per-group collector and explicit device IDs. Every selected tuple is
    expected to remain at zero.

    ``skip_injection`` drops the in-playbook prefix-injection + stabilization
    stage steps. Use it when prefixes are injected once by a dedicated setup
    task (``fpf_inject_bgp_prefixes``, e.g. the 8-STSW split-per-VF injection) so
    the netcastle run injects exactly once from setup. ``prefix_count`` is then
    used only as the EXPECTED converged count for the per-GTSW/per-lane checks.

    ``bgp_rib_restart_reconverge`` switches the BGP RIB checks to the
    restart-aware contract: tolerate null/error samples while bgpd is stopped,
    require recovery to ``prefix_count`` within ``reconvergence_sla_sec`` of the
    recorded restart timestamp, and require the final valid sample to remain
    healthy.

    ``fsdb_rib_restart_reconverge`` applies the same contract to FSDB ribMap,
    using the separately recorded restart timestamp so an earlier disruption
    timestamp remains available to drain-window checks.

    ``prod_prefix_restart_recovery_sla_sec`` replaces ordinary production-prefix
    stability with HRT restart recovery: baseline immediately before restart,
    tolerate outage rows, then require full-set recovery within this many seconds
    from the first complete sample after restart completion/final outage and a
    healthy final sample. ``hrt_restart_tolerant_hosts`` applies the matching
    null-tolerant-but-exact policy to HRT bulk and remote-failure checks only for
    the intentionally restarted host(s); other hosts remain strict.

    ``fsdb_expected_total`` overrides the expected HRT FSDB session count
    (default ``32`` — every one of the 4 GPUs subscribes to all 8 GTSWs, so a
    BE node has a FIXED 4 x 8 = 32 sessions regardless of how many GTSWs we
    observe; the old ``len(gtsws) * 4`` default was wrong when ``gtsws`` is just
    the observer subset). ``skip_fsdb_session_precheck``
    drops the FSDB-session precheck (restore phase: the lab may still be in
    graceful-restart hold from the disrupt, which is informational, not a
    restore failure). ``skip_port_state_precheck`` similarly drops the PORT_STATE
    precheck on a restore half that re-enables ports in-stage: the preceding
    disrupt left the impacted uplinks DOWN, so the precheck (which runs before the
    in-stage re-enable + settle) would FAIL on the still-/just-re-enabled ports;
    the postcheck still re-asserts full port/plane recovery after the settle.
    ``convergence_settle_sec`` advances the convergence
    postchecks' window past the recovery (restore phase) so the impacted lane's
    re-converge transient isn't flagged as post-convergence instability.

    ``use_bgp_snapshot`` replaces the BGP-session *establish* checks (precheck,
    convergence-timing disruption postcheck, and full postcheck) with a single
    BGP-session SNAPSHOT check: the established set is tallied at precheck (no
    fail on baseline-down sessions) and asserted unchanged at postcheck. Use for
    link-event tests (interface enable / undrain), where the lab fabric may have
    sessions down at baseline and a GPU-link event does not change — nor flap —
    the GTSW<->STSW BGP sessions (so the uptime<10s convergence-timing check
    does not apply).

    ``host_spray_label`` (default "") is passed through as the ``label=`` of the
    generic host-spray postcheck so a results-table row can be self-describing
    (e.g. "[longevity] all 4 lanes >75Gbps"). Empty means no prefix — no change
    for existing callers.

    ``host_spray_excluded_lanes_by_host`` (default None) drops the given beth
    lanes (per host) from the generic host-spray postcheck entirely — no floor,
    no spread, no drain assertion on them. Used when a lane is legitimately
    drained in the steady state under test (e.g. an STSW-plane drain that takes
    the lane-0 spine down), so only the surviving lanes are held to the floor.
    None means no exclusion — no change for existing callers.

    ``impacted_lanes_drained`` (default None) marks the given fabric lanes as
    DRAINED/impacted for a drain-longevity config where the drain STAYS in effect
    through the whole soak (e.g. tc34/tc54: stsw001.s001 -> lane 0). When set
    (non-empty) the impacted lanes are treated CONSISTENTLY as drained across:
      - plane-status: ``mode="drain"`` (those planes must be/stay DRAINED while
        every other plane stays UP) instead of the ``all_up`` recovery contract.
      - host-spray: the impacted NIC lanes (beth{lane}) are POSITIVELY asserted
        ~0 (egress < ``impacted_spray_max_gbps``) on every spray host while the
        floor/spread are judged only over the remaining lanes.
      - convergence (FSDB ribMap / BGP RIB per-GTSW, HRT bulk per-lane): the
        impacted lane is EXEMPTED — it is not asserted to converge to
        ``prefix_count`` (the drained plane legitimately drops on that lane);
        every other lane keeps the full convergence assertion.
      - HRT remote-failure: the impacted lanes are EXEMPTED from the "stable"
        (must-stay-0) assertion (a drain may surface negative routes on the
        impacted lane); the unimpacted lanes keep the stable/last-sample contract.
    The HRT FSDB-SESSION precheck/postcheck is deliberately NOT affected — an
    STSW-side drain does not touch the GPU<->GTSW HRT subscription, so that check
    stays STRICT (32/32). ``impacted_spray_max_gbps`` (default 10.0) is the
    drained-lane egress ceiling. None/empty keeps every check byte-identical to a
    non-drained caller (so tc35 undrain / tc36 restore stay all_up + golden).

    Assumes collectors are already running (via FpfStartCollectorsTask in
    setup_tasks). This playbook:
      1. Injects prefixes on STSW devices (test_case_start_time aligns here)
      2. Waits for stabilization (prefixes programmed on GTSW/HRT)
      3. Runs disruption steps (or soak for stable-state tests)
      4. Postchecks query live collectors for time-windowed convergence
    """
    from taac.health_checks.healthcheck_definitions import (
        create_fpf_bgp_rib_convergence_check,
        create_fpf_fsdb_ribmap_convergence_check,
        create_fpf_hrt_bulk_convergence_check,
        create_fpf_hrt_plane_status_check,
        create_fpf_hrt_remote_failure_convergence_check,
        create_fpf_prod_hrt_prefix_stability_check,
    )
    from taac.stages.stage_definitions import (
        create_steps_stage,
    )
    from taac.steps.step_definitions import (
        create_fpf_bgp_prefix_injection_step,
        create_fpf_ensure_traffic_step,
        create_longevity_step,
    )

    from taac.libs.fpf.fpf_thresholds import (
        ACTIVE as FPF_ACTIVE_THRESHOLDS,
    )

    services = services_to_check or ["bgpd", "fsdb", "wedge_agent", "qsfp_service"]
    resolved_lanes = lanes if lanes is not None else [0, 1]
    resolved_hrt_device_ids = hrt_device_ids or sorted(
        {
            int(device_id)
            for group in (rf_vf_groups or [])
            for device_id in group.get("device_ids", [0])
        }
    ) or [0]
    # Default the expected HRT FSDB session count to 32 — the per-BE-node count
    # is FIXED at 32 (every one of the 4 GPUs subscribes to all 8 GTSWs:
    # 4 x 8 = 32) regardless of how many GTSWs we observe. The previous
    # ``len(gtsws) * 4`` default was wrong whenever ``gtsws`` is the observer
    # subset (e.g. 2 observers -> 8), which produced a false FAIL
    # "32/32 CONNECTED (expected 8)" on a healthy device. The
    # ``fsdb_expected_total`` override path is preserved for callers that need a
    # non-32 value (e.g. disruption configs expecting impacted lanes).
    fsdb_sessions_per_host = (
        fsdb_expected_total if fsdb_expected_total is not None else 32
    )

    # Drain-longevity impacted-lane handling (opt-in via impacted_lanes_drained):
    # the drain STAYS in effect through the soak, so the impacted fabric lanes
    # (plane == lane on the monitored GPU) are treated consistently as drained
    # across plane-status / host-spray / convergence / remote-failure below. Empty
    # => every check is byte-identical to a non-drained caller.
    drained_lanes = sorted(set(impacted_lanes_drained or []))
    drained_hrt_tuples = (
        _fpf_global_lanes_to_hrt_tuples(
            hosts, drained_lanes, resolved_hrt_device_ids
        )
        if drained_lanes and resolved_hrt_device_ids != [0]
        else {}
    )
    # host -> ["beth{lane}", ...] for the host-spray ~0 assertion on the impacted
    # NIC lanes (draining a fabric lane stops egress on that lane's beth on EVERY
    # spray host attached to the plane, not just the drained circuit's host).
    spray_impacted_by_host = (
        {h: [f"beth{lane}" for lane in drained_lanes] for h in spray_hosts}
        if drained_lanes and spray_hosts
        else None
    )

    # Generic (non-convergence) check set — SSH/device-shell generic checks +
    # ODS-only checks (discard/congestion counters, HRT mem/driver, host-spray)
    # + the matching prechecks and snapshot checks. Factored into
    # _build_fpf_generic_checks so v1 / service-restart share the exact same
    # logic; the assembled v2 lists below are byte-for-byte identical to before.
    prechecks, generic_postchecks, snapshot_checks = _build_fpf_generic_checks(
        hosts=hosts,
        services=services,
        gtsws=gtsws,
        trigger_stsws=trigger_stsws,
        skip_ssh_dependent_checks=skip_ssh_dependent_checks,
        fsdb_sessions_per_host=fsdb_sessions_per_host,
        prod_prefixes=prod_prefixes,
        hrt_memory_hosts=hrt_memory_hosts,
        hrt_driver_hosts=hrt_driver_hosts,
        spray_hosts=spray_hosts,
        ods_entities=ods_entities,
        use_bgp_snapshot=use_bgp_snapshot,
        skip_fsdb_session_precheck=skip_fsdb_session_precheck,
        skip_fsdb_session_postcheck=skip_fsdb_session_postcheck,
        skip_port_state_precheck=skip_port_state_precheck,
        ods_discard_informational=ods_discard_informational,
        host_spray_label=host_spray_label,
        host_spray_excluded_lanes_by_host=host_spray_excluded_lanes_by_host,
        spray_impacted_by_host=spray_impacted_by_host,
        spray_impacted_max_gbps=impacted_spray_max_gbps,
        # Disrupted-lane (drain-then-recover) exemption for the GENERIC host-spray
        # floor on GR-beyond / kill configs (e.g. tc06/tc08): the disrupted lane's
        # beth is exempted from the all-lanes floor (route recovery is covered by
        # the convergence checks). Per-host dict so tc08 (only the DUT-cabled host
        # drains) differs from tc06 (both hosts' lane-0 purge). None => unchanged.
        spray_excluded_by_host=spray_recovering_by_host,
        assert_bgp_reconvergence=assert_bgp_reconvergence,
        reconvergence_service=reconvergence_service,
        reconvergence_sla_sec=reconvergence_sla_sec,
        reconvergence_hosts=reconvergence_hosts,
        out_congestion_last_minute_max=out_congestion_last_minute_max,
        host_spray_transform_desc=host_spray_transform_desc,
        hrt_device_ids=resolved_hrt_device_ids,
    )

    # Stage steps: inject → stabilize → disruption (or soak). When
    # skip_injection, prefixes are injected once by a setup task instead.
    stage_steps = []
    if not skip_injection:
        stage_steps.extend(
            [
                create_fpf_bgp_prefix_injection_step(
                    devices=trigger_stsws,
                    count=prefix_count,
                    community_list=community_list,
                    description=(
                        f"Inject {prefix_count} BGP prefixes on "
                        f"{', '.join(trigger_stsws)}"
                    ),
                ),
                create_longevity_step(
                    duration=stabilization_delay_sec,
                    description=(
                        f"Stabilization wait — {stabilization_delay_sec}s for "
                        f"prefixes to program on GTSW/HRT"
                    ),
                ),
            ]
        )
    # STRICT traffic precheck at the head of every playbook: verify all 4 RDMA
    # planes (beth0-3) carry traffic; if overall traffic has collapsed to ~0 (all
    # 4 lanes dead — e.g. a prior playbook's disruption killed ib_write_bw)
    # restart it and re-verify; FAIL HARD if a plane still can't carry traffic
    # (a real fabric/plane wedge a restart can't fix — fail fast rather than run a
    # contaminated test). A single dead lane is logged but NOT auto-restarted.
    # Hosts default to spray_hosts (server = spray_hosts[0], clients = the rest);
    # no-op when skip_ssh (spray_hosts is None). Runs before the disruption/soak.
    _ib_server = restart_ib_traffic_server
    _ib_clients = restart_ib_traffic_clients
    if _ib_server is None and spray_hosts and len(spray_hosts) >= 2:
        _ib_server = spray_hosts[0]
        _ib_clients = list(spray_hosts[1:])
    if ib_traffic_config:
        stage_steps.append(
            create_fpf_ensure_traffic_step(
                **ib_traffic_config,
                description=(
                    "Strict traffic readiness: validate the canonical process "
                    "and egress contract; recover only after the prior verdict"
                ),
            )
        )
    elif _ib_server and _ib_clients:
        stage_steps.append(
            create_fpf_ensure_traffic_step(
                server=_ib_server,
                clients=_ib_clients,
                description=(
                    "Strict traffic precheck: ensure all 4 planes carry traffic "
                    "(restart ib_write_bw if collapsed; fail hard on a plane wedge)"
                ),
            )
        )
    if disruption_steps:
        stage_steps.extend(disruption_steps)
    elif soak_duration_sec > 0:
        stage_steps.append(
            create_longevity_step(
                duration=soak_duration_sec,
                description="Stable-state soak — no disruption",
            ),
        )

    convergence_postchecks = []
    for lane_id, gtsw in enumerate(gtsws):
        # Drain exemption: the impacted lane's GTSW serves the drained plane
        # (gtsw00{i} -> lane{i-1}), whose prefixes legitimately drop on that lane,
        # so we do NOT assert it converges to prefix_count. Every other lane keeps
        # the full FSDB ribMap + BGP RIB convergence assertion.
        if lane_id in drained_lanes:
            continue
        lane_map = {str(lane_id): gtsw}
        convergence_postchecks.append(
            create_fpf_fsdb_ribmap_convergence_check(
                lane_map=lane_map,
                expected_matched=prefix_count,
                use_live_collectors=True,
                mode="restart" if fsdb_rib_restart_reconverge else None,
                reconverge_sla_sec=(
                    FPF_ACTIVE_THRESHOLDS.fsdb_restart_reconverge_sla_sec
                    if fsdb_rib_restart_reconverge
                    else None
                ),
                use_restart_time=fsdb_rib_restart_reconverge,
                signal1_e2e_max_sec=FPF_ACTIVE_THRESHOLDS.convergence_signal1_e2e_max_sec,
                signal2_local_max_sec=FPF_ACTIVE_THRESHOLDS.convergence_signal2_local_max_sec,
                signal3_stability_duration_sec=FPF_ACTIVE_THRESHOLDS.convergence_signal3_stability_duration_sec,
                settle_sec=convergence_settle_sec or None,
                stability_mode=convergence_blip_mode,
                check_id=f"fpf_fsdb_convergence_lane{lane_id}",
            )
        )
        convergence_postchecks.append(
            create_fpf_bgp_rib_convergence_check(
                lane_map=lane_map,
                expected_matched=prefix_count,
                use_live_collectors=True,
                mode="restart" if bgp_rib_restart_reconverge else None,
                reconverge_sla_sec=(
                    reconvergence_sla_sec
                    if bgp_rib_restart_reconverge
                    else None
                ),
                signal1_e2e_max_sec=FPF_ACTIVE_THRESHOLDS.convergence_signal1_e2e_max_sec,
                signal2_local_max_sec=FPF_ACTIVE_THRESHOLDS.convergence_signal2_local_max_sec,
                signal3_stability_duration_sec=FPF_ACTIVE_THRESHOLDS.convergence_signal3_stability_duration_sec,
                settle_sec=convergence_settle_sec or None,
                stability_mode=convergence_blip_mode,
                check_id=f"fpf_bgp_convergence_lane{lane_id}",
            )
        )
    for lane_id in resolved_lanes:
        # Drain exemption: the drained plane's HRT bulk count drops on the
        # impacted lane, so it is not asserted to converge to prefix_count.
        if lane_id in drained_lanes:
            continue
        convergence_postchecks.append(
            create_fpf_hrt_bulk_convergence_check(
                lanes=[lane_id],
                device_ids=resolved_hrt_device_ids,
                expected_per_lane={str(lane_id): prefix_count},
                use_live_collectors=True,
                signal1_e2e_max_sec=FPF_ACTIVE_THRESHOLDS.convergence_signal1_e2e_max_sec,
                signal2_local_max_sec=FPF_ACTIVE_THRESHOLDS.convergence_signal2_local_max_sec,
                signal3_stability_duration_sec=FPF_ACTIVE_THRESHOLDS.convergence_signal3_stability_duration_sec,
                # settle past the recovery (restore phase) so the impacted lane's
                # re-converge transient isn't flagged as post-convergence churn.
                settle_sec=convergence_settle_sec or None,
                stability_mode=convergence_blip_mode,
                restart_tolerant_hosts=hrt_restart_tolerant_hosts,
                check_id=f"fpf_hrt_convergence_lane{lane_id}",
            )
        )
    # For process-disruption configs the HRT remote-failure (negative-route)
    # count legitimately blips during the disruption and fully clears afterwards
    # (e.g. GR-beyond/coldboot clear in ~36-57s, last=0). The remote-failure
    # "stable" direction is selected by ``convergence_blip_mode`` (preferred) or
    # the legacy ``remote_failure_last_sample`` flag, or the new
    # ``remote_failure_last_n`` flag (agent kill recovery mode):
    #   "last_sample"      -> stable_last_sample (MODE A: only last sample == 0)
    #   "skip_null_strict" -> stable_skip_null_strict (MODE B: every non-null == 0)
    #   "strict"/default   -> stable (every sample == 0)
    #   remote_failure_last_n=True -> stable_last_n (last N non-null samples == 0)
    if remote_failure_last_n:
        _rf_direction = "stable_last_n"
    elif convergence_blip_mode == "last_sample":
        _rf_direction = "stable_last_sample"
    elif convergence_blip_mode == "skip_null_strict":
        _rf_direction = "stable_skip_null_strict"
    elif remote_failure_last_sample:
        _rf_direction = "stable_last_sample"
    else:
        _rf_direction = "stable"
    # Drain exemption: an impacted lane may change its remote-failure count, so
    # it is dropped from the stable assertion. Every unimpacted lane retains its
    # configured stable/last-sample contract.
    if rf_vf_groups:
        for _g in rf_vf_groups:
            _glanes, _gexpected = _fpf_rf_stable_scope(
                _g,
                (lane for lane in resolved_lanes if lane not in drained_lanes),
            )
            if not _glanes:
                continue
            convergence_postchecks.append(
                create_fpf_hrt_remote_failure_convergence_check(
                    lanes=_glanes,
                    device_ids=_g.get("device_ids", [0]),
                    expected_per_lane=_gexpected,
                    direction=_rf_direction,
                    use_live_collectors=True,
                    collector_name=f"hrt_remote_failure_{_g['suffix']}",
                    restart_tolerant_hosts=hrt_restart_tolerant_hosts,
                    check_id=f"fpf_remote_failure_stable_{_g['suffix']}",
                )
            )
    else:
        _stable_lanes = [lane for lane in resolved_lanes if lane not in drained_lanes]
        if _stable_lanes:
            convergence_postchecks.append(
                create_fpf_hrt_remote_failure_convergence_check(
                    lanes=_stable_lanes,
                    device_ids=resolved_hrt_device_ids,
                    direction=_rf_direction,
                    use_live_collectors=True,
                    restart_tolerant_hosts=hrt_restart_tolerant_hosts,
                    check_id="fpf_remote_failure_stable",
                )
            )
    # Fifth collector ↔ fifth validating check: production HRT prefix
    # reachability stability. Only added when the prod_hrt_prefix collector
    # was started (prod_prefixes supplied to FpfStartCollectorsTask).
    if prod_prefixes and drained_lanes:
        # Drain-longevity: the impacted plane stays DRAINED for the whole soak, so
        # the prod-prefix recovery (local_undrain) contract — which expects the
        # lane to come BACK reachable — does NOT apply. The longevity window opens
        # after the drain already settled, so the per-prefix stability baseline
        # (first in-window sample) already excludes the drained plane; the plain
        # stability check then asserts lane 0 STAYS drained (no further regression
        # of the remaining reachable planes).
        convergence_postchecks.append(
            create_fpf_prod_hrt_prefix_stability_check(
                settle_sec=prod_prefix_settle_sec or None,
                stability_mode=convergence_blip_mode,
                check_id="fpf_prod_hrt_prefix_stability",
            )
        )
    elif prod_prefixes and prod_prefix_recovery and local_prod_prefixes:
        # Recovery-anchored restore check: instead of a settle-and-baseline
        # stability assertion (which flags the recovery transient if the lane
        # comes back after the settle window), measure the LOCAL prefix's
        # restored lane returning to reachable — timed from the recorded recovery
        # moment (the re-enable / undrain command) to when the lane re-enters the
        # reachable set — and assert it within the SLA. REMOTE prefixes must not
        # churn. Robust regardless of how long recovery takes.
        convergence_postchecks.append(
            create_fpf_prod_hrt_prefix_stability_check(
                mode="local_undrain",
                local_prefixes=local_prod_prefixes,
                impacted_planes_by_host=impacted_planes_by_host or {},
                max_drain_sec=FPF_ACTIVE_THRESHOLDS.prod_prefix_recovery_sla_sec,
                check_id="fpf_prod_hrt_prefix_recovery",
            )
        )
    elif prod_prefixes and prod_prefix_restart_recovery_sla_sec is not None:
        convergence_postchecks.append(
            create_fpf_prod_hrt_prefix_stability_check(
                mode="restart_recovery",
                max_recovery_sec=prod_prefix_restart_recovery_sla_sec,
                check_id="fpf_prod_hrt_prefix_restart_recovery",
            )
        )
    elif prod_prefixes:
        convergence_postchecks.append(
            create_fpf_prod_hrt_prefix_stability_check(
                # settle past the recovery (restore phase): the plane comes back
                # mid-window, so take the per-prefix baseline after it settles
                # rather than flagging the recovery as a regression.
                settle_sec=prod_prefix_settle_sec or None,
                stability_mode=convergence_blip_mode,
                recovery_last_n=recovery_last_n,
                check_id="fpf_prod_hrt_prefix_stability",
            )
        )
    # HRT plane-status (hrtctl show plane-status). For a drain-longevity config
    # (impacted_lanes_drained set) the impacted plane(s) must be/stay DRAINED
    # while every other plane stays UP (mode="drain", window auto-anchored at the
    # disruption time). Otherwise every plane must be UP (mode="all_up") — the
    # restore/undrain + stable-state contract; convergence_settle_sec advances the
    # window past the recovery transient so the re-up isn't flagged.
    if plane_status_check and prod_prefixes:
        if drained_lanes:
            convergence_postchecks.append(
                create_fpf_hrt_plane_status_check(
                    mode="drain",
                    impacted_planes=drained_lanes,
                    device_ids=resolved_hrt_device_ids,
                    impacted_tuples_by_host_device=drained_hrt_tuples or None,
                    check_id="fpf_hrt_plane_status_drain",
                )
            )
        else:
            convergence_postchecks.append(
                create_fpf_hrt_plane_status_check(
                    mode="all_up",
                    device_ids=resolved_hrt_device_ids,
                    settle_sec=convergence_settle_sec or None,
                    # Disruptive configs (convergence_blip_mode="last_sample") tolerate
                    # a mid-window plane UNKNOWN that recovers to UP (e.g. latched while
                    # HRT re-subscribes mid-coldboot); only the last sample must be UP.
                    stability_mode=convergence_blip_mode,
                    check_id="fpf_hrt_plane_status_all_up",
                )
            )

    # The old p50-based BGP convergence-timing postcheck (max_session_uptime_sec)
    # was removed: it fanned out to every endpoint device (observer GTSW + 8 STSW
    # planes) and divided by each device's own systemd restart epoch, so a
    # non-restarted observer's stale epoch produced absurd convergence values,
    # and the p50 hid slow outliers. Process-disruption configs now opt into the
    # DUT-scoped, pre-established-peer reconvergence SNAPSHOT check via
    # assert_bgp_reconvergence (added to snapshot_checks in _build_fpf_generic_checks).
    disruption_postchecks = []

    # Splice the disruption + convergence postchecks between the generic head
    # (SSH/device-shell checks) and the generic tail (ODS counters, HRT
    # mem/driver, host-spray) so the assembled order is byte-for-byte identical
    # to before the _build_fpf_generic_checks extraction.
    tail_len = _fpf_generic_postcheck_tail_len(
        skip_ssh_dependent_checks=skip_ssh_dependent_checks,
        hrt_memory_hosts=hrt_memory_hosts,
        hrt_driver_hosts=hrt_driver_hosts,
        spray_hosts=spray_hosts,
    )
    generic_head = generic_postchecks[: len(generic_postchecks) - tail_len]
    generic_tail = generic_postchecks[len(generic_postchecks) - tail_len :]

    postchecks = [
        *generic_head,
        *disruption_postchecks,
        *convergence_postchecks,
        *generic_tail,
        *(additional_postchecks or []),
    ]

    playbook_kwargs: dict[str, t.Any] = {
        "name": playbook_name,
        "prechecks": prechecks,
        "postchecks": postchecks,
        "snapshot_checks": snapshot_checks,
        "stages": [create_steps_stage(stage_id="disruption", steps=stage_steps)],
    }
    if cleanup_steps is not None:
        playbook_kwargs["cleanup_steps"] = cleanup_steps
    return Playbook(**playbook_kwargs)


def create_fpf_link_event_disrupt_playbook(
    *,
    gtsws: list[str],
    hosts: list[str],
    trigger_stsws: list[str],
    disruption_steps: list,
    prefix_count: int,
    community_list: str,
    stabilization_delay_sec: int,
    injected_lanes: list[int],
    impacted_lanes: list[int],
    impacted_lanes_by_host_gpu: dict,
    impacted_beths_by_host: dict,
    impacted_planes_by_host: dict,
    prod_prefixes: list[str] | None = None,
    hrt_memory_hosts: list[str] | None = None,
    hrt_driver_hosts: list[str] | None = None,
    spray_hosts: list[str] | None = None,
    flip_fsdb_session: bool = True,
    flip_discards: bool = True,
    injected_prefixes_withdrawn: bool = True,
    remote_failure_sla_sec: int = 30,
    transition_sla_sec: int = 30,
    fsdb_expected_total: int = 32,
    impacted_max_gbps: float = 10.0,
    ods_entities: list[str] | None = None,
    include_ssh_checks: bool = False,
    plane_status_mode: str | None = None,
    ods_discard_informational: bool = False,
    skip_injection: bool = False,
    rf_vf_groups: list | None = None,
    gtsw_convergence_settle_sec: int = 0,
    hrt_device_ids: list[int] | None = None,
    ib_traffic_config: t.Mapping[str, t.Any] | None = None,
    cleanup_steps: list | None = None,
    playbook_name: str = "fpf_link_event_disrupt",
) -> Playbook:
    """Disrupt-phase playbook for FPF link events (interface-disable / link-drain).

    ``gtsw_convergence_settle_sec`` (use with skip_injection): settles the
    GTSW-side ribMap/BGP convergence eval window past the disruption so a
    transient single-poll BGP-thrift read of 0 during the drain/disable (a query
    artifact — FSDB stays at the expected count) is not counted as a post-
    convergence drop. Default 0 = unchanged for in-playbook-injection callers.

    ``rf_vf_groups`` (8-STSW split-per-VF injection): list of
    ``{"suffix", "subnet", "lanes"}``. When given, BOTH HRT remote-failure checks
    are split per VF group, each scoped to that group's own lanes and reading its
    per-group narrow-subnet collector ("hrt_remote_failure_<suffix>"): (1) the
    "stable" check so each group asserts zero remote-failure where it IS reachable,
    not the other group's expected cross-plane failures, and (2) the disrupt
    "drain" convergence check so an impacted lane converges to only its own group's
    per-lane count (the aggregate collector would double-count the other group's
    always-failed routes on that lane -> false FAIL). Lanes spanning both groups
    emit one check per group.

    ``skip_injection`` drops the in-playbook prefix-injection + stabilization
    stage steps (prefixes injected once by the ``fpf_inject_bgp_prefixes`` setup
    task — 8-STSW split-per-VF injection). ``prefix_count`` then serves only as
    the EXPECTED converged count for the per-GTSW ribMap/BGP and per-lane HRT
    bulk checks.

    Injects stress prefixes, stabilizes, then runs the supplied disruption steps
    (disable+longevity, or port-drain+longevity). Postchecks assert the
    *disrupted* contract over this playbook's own collector window (test case
    start time is reset per-playbook by the runner):

      - HRT bulk: ``impacted_lanes`` withdrawn (last sample 0), other injected
        lanes still converge.
      - HRT remote-failure: impacted lanes 0->prefix_count within
        ``remote_failure_sla_sec``; the other lanes stay 0 (stable).
      - Prod/broad prefix: mode="transition" — impacted planes go
        reachable->unreachable within ``transition_sla_sec`` on every host.
      - Host-spray: impacted beths < ``impacted_max_gbps``; floor+fairness over
        the unimpacted lanes.
      - FSDB/HRT session: when ``flip_fsdb_session`` (interface-disable),
        overall == ``fsdb_expected_total`` - N with per-GPU0 reconciliation;
        when False (link-drain "control up"), sessions stay all-CONNECTED.
      - ODS discards/congestion: when ``flip_discards`` (interface-disable),
        assert loss >= 10000; when False (drain), keep the stable <= bound.
        When ``ods_discard_informational`` is True (e.g. tc36 STSW all
        connections down) the two DISCARD checks (``in_dst_null_discard``,
        ``in_discard``) are recorded as INFORMATIONAL (breach -> PASS with an
        ``[INFORMATIONAL]`` prefix in the message instead of FAIL) — expected
        transient loss during the disruption window. The two CONGESTION checks
        stay hard (a link event must not cause congestion). This mirrors the
        ``ods_discard_informational`` plumbing on the service-restart playbook.
      - BGP RIB + FSDB ribMap (GTSW-side): unchanged convergence to threshold.

    Generic SSH/device checks are intentionally omitted — this is the no-SSH
    collector/ODS validation path. Pair this with a v2 stable-state restore
    playbook (enable/undrain) sequenced immediately after.
    """
    from taac.health_checks.healthcheck_definitions import (
        create_fpf_bgp_rib_convergence_check,
        create_fpf_fsdb_ribmap_convergence_check,
        create_fpf_host_spray_check,
        create_fpf_hrt_bulk_convergence_check,
        create_fpf_hrt_driver_disconnect_check,
        create_fpf_hrt_fsdb_session_check,
        create_fpf_hrt_plane_status_check,
        create_fpf_hrt_remote_failure_convergence_check,
        create_fpf_hrt_system_memory_check,
        create_fpf_ods_counter_check,
        create_fpf_prod_hrt_prefix_stability_check,
    )
    from taac.libs.fpf.fpf_thresholds import (
        ACTIVE as FPF_ACTIVE_THRESHOLDS,
    )
    from taac.stages.stage_definitions import create_steps_stage
    from taac.steps.step_definitions import (
        create_fpf_bgp_prefix_injection_step,
        create_fpf_ensure_traffic_step,
        create_fpf_record_disruption_time_step,
        create_longevity_step,
    )

    # ---- Prechecks: assert healthy/stable BEFORE the disruption ----
    prechecks = [
        create_fpf_hrt_fsdb_session_check(
            hosts=hosts,
            expected_session_count=fsdb_expected_total,
            check_id="fpf_hrt_fsdb_session_precheck",
        ),
    ]
    if prod_prefixes:
        prechecks.append(
            create_fpf_prod_hrt_prefix_stability_check(
                check_id="fpf_prod_hrt_prefix_stability_precheck",
            )
        )
    if hrt_memory_hosts:
        prechecks.append(
            create_fpf_hrt_system_memory_check(
                hosts=hrt_memory_hosts,
                threshold_gib=FPF_ACTIVE_THRESHOLDS.hrt_system_memory_max_gib,
                check_id="fpf_hrt_system_memory_precheck",
            )
        )

    # Generic SSH/device-shell checks (require a Kerberos/SSH cert). Asserted on
    # the DUT GTSWs before the disruption: services up, no recent unclean exits,
    # memory within per-process bounds. BGP sessions are handled as a SNAPSHOT
    # check (below) rather than a precheck establish check: the lab fabric often
    # has a few sessions already down at baseline, and a GPU-link disable/drain
    # must not change the GTSW<->STSW BGP session count anyway. So we tally the
    # established sessions at precheck (no fail) and assert the post-disruption
    # count matches in the postcheck — like the other snapshot checks.
    _mem_thresholds = {
        "bgpd": 4.5 * (1024**3),
        "fsdb": 5 * (1024**3),
        "qsfp_service": 2 * (1024**3),
        "fboss_sw_agent": 9 * (1024**3),
        "fboss_hw_agent@0": 8 * (1024**3),
    }
    if include_ssh_checks:
        prechecks.extend(
            [
                create_systemctl_active_state_check(),
                create_unclean_exit_check(),
                create_memory_utilization_check(
                    threshold=5 * (1024**3),
                    threshold_by_service=_mem_thresholds,
                    start_time_jq_var="test_case_start_time",
                ),
            ]
        )

    # ---- Stage: inject -> stabilize -> disruption ----
    # When skip_injection, prefixes are injected once by a setup task; the stage
    # starts at the disruption-time stamp.
    stage_steps = []
    # STRICT traffic precheck at the stage HEAD: verify all 4 RDMA planes carry
    # traffic (restart ib_write_bw if collapsed; fail hard on a plane wedge).
    # No-op when skip_ssh (spray_hosts is None / < 2 hosts).
    if ib_traffic_config:
        stage_steps.append(
            create_fpf_ensure_traffic_step(
                **ib_traffic_config,
                description=(
                    "Strict traffic readiness: validate the canonical process "
                    "and egress contract; recover only after the prior verdict"
                ),
            )
        )
    elif spray_hosts and len(spray_hosts) >= 2:
        stage_steps.append(
            create_fpf_ensure_traffic_step(
                server=spray_hosts[0],
                clients=list(spray_hosts[1:]),
                description=(
                    "Strict traffic precheck: ensure all 4 planes carry traffic "
                    "(restart ib_write_bw if collapsed; fail hard on a plane wedge)"
                ),
            )
        )
    if not skip_injection:
        stage_steps.extend(
            [
                create_fpf_bgp_prefix_injection_step(
                    devices=trigger_stsws,
                    count=prefix_count,
                    community_list=community_list,
                    description=f"Inject {prefix_count} BGP prefixes on {', '.join(trigger_stsws)}",
                ),
                create_longevity_step(
                    duration=stabilization_delay_sec,
                    description=(
                        f"Stabilization wait — {stabilization_delay_sec}s for prefixes "
                        f"to program on GTSW/HRT before disruption"
                    ),
                ),
            ]
        )
    stage_steps.extend(
        [
            # Stamp the disruption moment so the prod-prefix transition check
            # measures reachable->unreachable from here (30s SLA), not from
            # test_case_start (which precedes the stabilization wait).
            create_fpf_record_disruption_time_step(),
            *disruption_steps,
        ]
    )

    sig1 = FPF_ACTIVE_THRESHOLDS.convergence_signal1_e2e_max_sec
    sig2 = FPF_ACTIVE_THRESHOLDS.convergence_signal2_local_max_sec
    sig3 = FPF_ACTIVE_THRESHOLDS.convergence_signal3_stability_duration_sec
    resolved_hrt_device_ids = hrt_device_ids or sorted(
        {
            int(device_id)
            for group in (rf_vf_groups or [])
            for device_id in group.get("device_ids", [0])
        }
    ) or [0]

    postchecks = []

    # GTSW-side convergence (UNCHANGED — the GTSW<->GPU link being down does not
    # affect GTSW BGP/FSDB; prefixes remain present and converged).
    #
    # gtsw_convergence_settle_sec: when prefixes are injected by a SETUP TASK
    # (skip_injection=True), the injected prefixes are already converged when this
    # disrupt playbook starts, so T2 ≈ window_start and the 3-signal Signal-3
    # stability window overlaps the disruption. A drain/disable can make the
    # GTSW's BGP thrift query momentarily read 0 for a single poll (a transient
    # query artifact — the FSDB ribMap on the same GTSW stays at the expected
    # count, proving the prefixes never left), which Signal-3 would otherwise count
    # as a drop. Settling the window past the disruption skips that artifact and
    # measures the post-disruption steady state. Default 0 keeps existing callers
    # (in-playbook injection) byte-identical.
    _gtsw_settle = gtsw_convergence_settle_sec or None
    for lane_id, gtsw in enumerate(gtsws):
        lane_map = {str(lane_id): gtsw}
        postchecks.append(
            create_fpf_fsdb_ribmap_convergence_check(
                lane_map=lane_map,
                expected_matched=prefix_count,
                use_live_collectors=True,
                signal1_e2e_max_sec=sig1,
                signal2_local_max_sec=sig2,
                signal3_stability_duration_sec=sig3,
                settle_sec=_gtsw_settle,
                check_id=f"fpf_fsdb_convergence_lane{lane_id}",
            )
        )
        postchecks.append(
            create_fpf_bgp_rib_convergence_check(
                lane_map=lane_map,
                expected_matched=prefix_count,
                use_live_collectors=True,
                signal1_e2e_max_sec=sig1,
                signal2_local_max_sec=sig2,
                signal3_stability_duration_sec=sig3,
                settle_sec=_gtsw_settle,
                check_id=f"fpf_bgp_convergence_lane{lane_id}",
            )
        )

    # Lane -> host-NIC mapping note for debuggability (e.g. "→ beth0@rtptest1544").
    # Derived from the circuits' impacted beths (beth index = gpu*8 + lane, so
    # lane = index % 8). Surfaced verbatim in the bulk/remote-failure messages so
    # a reviewer sees which physical NIC each impacted fabric lane corresponds to.
    _lane_to_beths: dict[str, list[str]] = {}
    for _host, _beths in (impacted_beths_by_host or {}).items():
        for _beth in _beths:
            _digits = "".join(ch for ch in _beth if ch.isdigit())
            if not _digits:
                continue
            _lane = str(int(_digits) % 8)
            _lane_to_beths.setdefault(_lane, []).append(f"{_beth}@{_host}")
    lane_labels = {
        _lane: "→ " + ", ".join(sorted(_v)) for _lane, _v in _lane_to_beths.items()
    }

    # ``injected_prefixes_withdrawn`` distinguishes interface-disable (the port
    # goes DOWN -> ALL prefixes on the lane withdrawn -> bulk -> 0, remote-failure
    # rises) from a community-based soft-DRAIN (depreferences the production VF
    # plane — caught by the prod-prefix transition below — but does NOT withdraw
    # the directly-injected test prefixes, whose count in HRT is unchanged). For
    # a drain we therefore do NOT expect the injected prefixes to withdraw: the
    # impacted lane is asserted as a normal converged lane and remote-failure
    # stays stable on every injected lane. The real drain disruption signal is
    # the prod-prefix transition + host-spray.
    impacted_hosts = sorted(impacted_lanes_by_host_gpu.keys())
    bulk_impacted = impacted_lanes if injected_prefixes_withdrawn else []
    impacted_hrt_tuples: dict[str, dict[str, list[int]]] = {}
    if resolved_hrt_device_ids != [0]:
        for _host, _gpus in impacted_lanes_by_host_gpu.items():
            for _gpu_id, _global_lanes in _gpus.items():
                for _global_lane in _global_lanes:
                    _device_id = 2 * int(_gpu_id) + int(_global_lane) // 4
                    _local_lane = int(_global_lane) % 4
                    if _device_id not in resolved_hrt_device_ids:
                        continue
                    _lanes = impacted_hrt_tuples.setdefault(_host, {}).setdefault(
                        str(_device_id), []
                    )
                    if _local_lane not in _lanes:
                        _lanes.append(_local_lane)
    # When the injected prefixes withdraw (disable) only the impacted host's lane
    # changes -> scope to it. When they don't (drain) the injected prefixes stay
    # converged on EVERY host -> evaluate all hosts.
    bulk_only_hosts = (
        impacted_hosts
        if injected_prefixes_withdrawn and resolved_hrt_device_ids == [0]
        else None
    )
    postchecks.append(
        create_fpf_hrt_bulk_convergence_check(
            lanes=injected_lanes,
            device_ids=resolved_hrt_device_ids,
            expected_per_lane={str(lane): prefix_count for lane in injected_lanes},
            impacted_lanes=bulk_impacted,
            impacted_tuple_lanes_by_host_device=(
                impacted_hrt_tuples if injected_prefixes_withdrawn else None
            ),
            withdrawn_max_count=0,
            lane_labels=lane_labels,
            only_hosts=bulk_only_hosts,
            use_live_collectors=True,
            signal1_e2e_max_sec=sig1,
            signal2_local_max_sec=sig2,
            signal3_stability_duration_sec=sig3,
            check_id="fpf_hrt_bulk_disrupt",
        )
    )

    # HRT remote-failure. For interface-disable the impacted lane rises 0->count
    # (drain direction); for a soft-drain the injected prefixes don't withdraw, so
    # there is no rise — every injected lane stays stable. Scoped to the impacted
    # host(s) for the rise; the stable assertion covers the injected lanes only
    # (a non-injected lane can show unrelated nonzero samples).
    if injected_prefixes_withdrawn and impacted_lanes:
        if rf_vf_groups:
            # Per-VF-group convergence: the impacted lane counts ONLY its own
            # group's newly-failed routes. The aggregate 5000::/16 collector would
            # also count the other group's always-failed cross-plane routes on the
            # same lane (VF1 lane sees dd rise 0->count PLUS ee's persistent count),
            # yielding count*2 vs an expected count -> false FAIL. Read the group's
            # narrow-subnet collector and scope each check to the group's own
            # impacted lanes; split into two checks when the impacted set spans
            # both groups.
            for _g in rf_vf_groups:
                if resolved_hrt_device_ids == [0]:
                    _glanes = [
                        lane for lane in _g["lanes"] if lane in impacted_lanes
                    ]
                    _group_impacted = {}
                else:
                    _group_devices = {int(d) for d in _g.get("device_ids", [0])}
                    _group_impacted = {
                        host: {
                            device_id: tuple_lanes
                            for device_id, tuple_lanes in devices.items()
                            if int(device_id) in _group_devices
                        }
                        for host, devices in impacted_hrt_tuples.items()
                    }
                    _group_impacted = {
                        host: devices
                        for host, devices in _group_impacted.items()
                        if devices
                    }
                    _glanes = sorted(
                        {
                            lane
                            for devices in _group_impacted.values()
                            for tuple_lanes in devices.values()
                            for lane in tuple_lanes
                        }
                    )
                if not _glanes:
                    continue
                postchecks.append(
                    create_fpf_hrt_remote_failure_convergence_check(
                        lanes=_glanes,
                        device_ids=_g.get("device_ids", [0]),
                        expected_per_lane={str(lane): prefix_count for lane in _glanes},
                        direction="drain",
                        max_convergence_sec=remote_failure_sla_sec,
                        lane_labels=lane_labels,
                        only_hosts=impacted_hosts,
                        tuple_lanes_by_host_device=_group_impacted,
                        use_live_collectors=True,
                        collector_name=f"hrt_remote_failure_{_g['suffix']}",
                        check_id=f"fpf_remote_failure_impacted_{_g['suffix']}",
                    )
                )
        else:
            postchecks.append(
                create_fpf_hrt_remote_failure_convergence_check(
                    lanes=impacted_lanes,
                    device_ids=resolved_hrt_device_ids,
                    expected_per_lane={
                        str(lane): prefix_count for lane in impacted_lanes
                    },
                    direction="drain",
                    max_convergence_sec=remote_failure_sla_sec,
                    lane_labels=lane_labels,
                    only_hosts=impacted_hosts,
                    use_live_collectors=True,
                    check_id="fpf_remote_failure_impacted",
                )
            )
    stable_rf = (
        injected_lanes
        if resolved_hrt_device_ids != [0]
        else [
            lane
            for lane in injected_lanes
            if not (injected_prefixes_withdrawn and lane in impacted_lanes)
        ]
    )
    if stable_rf and rf_vf_groups:
        # Per-VF-group: assert zero remote failures on every mapped device/local
        # plane tuple, reading the group's narrow-subnet collector.
        for _g in rf_vf_groups:
            _glanes, _gexpected = _fpf_rf_stable_scope(_g, stable_rf)
            if not _glanes:
                continue
            postchecks.append(
                create_fpf_hrt_remote_failure_convergence_check(
                    lanes=_glanes,
                    device_ids=_g.get("device_ids", [0]),
                    expected_per_lane=_gexpected,
                    direction="stable",
                    only_hosts=impacted_hosts,
                    excluded_tuple_lanes_by_host_device=(
                        impacted_hrt_tuples if injected_prefixes_withdrawn else None
                    ),
                    use_live_collectors=True,
                    collector_name=f"hrt_remote_failure_{_g['suffix']}",
                    check_id=f"fpf_remote_failure_unimpacted_stable_{_g['suffix']}",
                )
            )
    elif stable_rf:
        postchecks.append(
            create_fpf_hrt_remote_failure_convergence_check(
                lanes=stable_rf,
                device_ids=resolved_hrt_device_ids,
                direction="stable",
                only_hosts=impacted_hosts,
                use_live_collectors=True,
                check_id="fpf_remote_failure_unimpacted_stable",
            )
        )

    # Prod/broad prefix transition: impacted planes go unreachable within SLA,
    # evaluated on every registered prod-prefix host.
    if prod_prefixes:
        postchecks.append(
            create_fpf_prod_hrt_prefix_stability_check(
                mode="transition",
                impacted_planes_by_host=impacted_planes_by_host,
                max_transition_sec=float(transition_sla_sec),
                check_id="fpf_prod_hrt_prefix_transition",
            )
        )

    # HRT plane-status (hrtctl show plane-status): for a DRAIN the impacted
    # plane(s) go DRAINED while every other plane stays UP. Only added when the
    # caller opts in via plane_status_mode="drain" (link/device drain) — a port
    # disable shows the plane DOWN, not DRAINED, so it is out of this contract.
    # New-SDK MWG2 maps each GPU/global lane to one exact device/local plane;
    # legacy dev0 callers retain the lane-only contract.
    if plane_status_mode == "drain" and prod_prefixes and impacted_lanes:
        postchecks.append(
            create_fpf_hrt_plane_status_check(
                mode="drain",
                impacted_planes=impacted_lanes,
                device_ids=resolved_hrt_device_ids,
                impacted_tuples_by_host_device=impacted_hrt_tuples or None,
                check_id="fpf_hrt_plane_status_drain",
            )
        )

    # Host-spray: impacted beths drained (<impacted_max_gbps); floor+fairness
    # on the unimpacted lanes. Draining a fabric lane (the GTSW plane serving it)
    # stops egress on that lane's beth for EVERY traffic host attached to the
    # plane — not just the directly-drained circuit's host. So the impacted beth
    # (beth{lane}) is expected at ~0 on ALL spray hosts; mark it impacted on each
    # so the floor/spread are asserted only over the genuinely unimpacted lanes.
    if spray_hosts:
        spray_impacted_by_host = {
            h: [f"beth{lane}" for lane in impacted_lanes] for h in spray_hosts
        }
        postchecks.append(
            create_fpf_host_spray_check(
                hosts=spray_hosts,
                min_egress_gbps=FPF_ACTIVE_THRESHOLDS.host_spray_min_egress_gbps,
                max_spread_gbps=FPF_ACTIVE_THRESHOLDS.host_spray_max_spread_gbps,
                impacted_lanes_by_host=spray_impacted_by_host,
                impacted_max_gbps=impacted_max_gbps,
                check_id="fpf_host_spray_disrupt",
            )
        )

    # FSDB/HRT session reconciliation.
    if flip_fsdb_session:
        postchecks.append(
            create_fpf_hrt_fsdb_session_check(
                hosts=hosts,
                expected_session_count=fsdb_expected_total,
                device_ids=(
                    resolved_hrt_device_ids
                    if resolved_hrt_device_ids != [0]
                    else None
                ),
                planes_per_device=(
                    4 if resolved_hrt_device_ids != [0] else None
                ),
                impacted_lanes_by_host_gpu=(
                    impacted_lanes_by_host_gpu
                    if resolved_hrt_device_ids == [0]
                    else None
                ),
                impacted_tuples_by_host_device=(
                    impacted_hrt_tuples
                    if resolved_hrt_device_ids != [0]
                    else None
                ),
                check_id="fpf_hrt_fsdb_session_disrupt",
            )
        )
    else:
        # Link-drain "control up": sessions stay fully CONNECTED.
        postchecks.append(
            create_fpf_hrt_fsdb_session_check(
                hosts=hosts,
                expected_session_count=fsdb_expected_total,
                device_ids=(
                    resolved_hrt_device_ids
                    if resolved_hrt_device_ids != [0]
                    else None
                ),
                planes_per_device=(
                    4 if resolved_hrt_device_ids != [0] else None
                ),
                check_id="fpf_hrt_fsdb_session_stable",
            )
        )

    # ODS discards/congestion (ODS-only, no SSH). interface-disable flips the
    # expectation to assert real packet loss; drain keeps the clean bound.
    # When ods_discard_informational is True (e.g. tc36: shutting an entire
    # STSW->GTSW bundle), expected transient loss on the impacted plane is
    # recorded against the pre-test baseline without failing the test. Final
    # discard recovery and both CONGESTION checks remain hard. This mirrors the
    # same knob on the service-restart playbook.
    # ODS discard/congestion checks scoped to the observer GTSWs only — STSWs are
    # deliberately not monitored (matches create_fpf_endpoints excluding STSWs from
    # per-device checks). Callers can still pass explicit ods_entities to override.
    ods_entity_desc = ",".join(ods_entities or gtsws)
    ods_reduce = r"groupby(entity, (\S+?\.\S+?)\..*, %1),sum"
    if ods_discard_informational:
        # Same four-check shape as _build_fpf_generic_checks but inline (the
        # link-event playbook does not otherwise route through that helper).
        postchecks.extend(
            [
                create_fpf_ods_counter_check(
                    entity_desc=ods_entity_desc,
                    key_desc="regex(fboss.agent.eth.*discards.sum.60),filter(.*in_dst_null.*)",
                    validation_expr=f"<= {FPF_ACTIVE_THRESHOLDS.ods_in_dst_null_discard_max}",
                    reduce_desc=ods_reduce,
                    counter_name="in_dst_null_discard",
                    shorten_pass_url=True,
                    baseline_excess_max=FPF_ACTIVE_THRESHOLDS.ods_in_dst_null_discard_max,
                    transient_excess_informational=True,
                    check_id="ods_in_dst_null_discard",
                ),
                create_fpf_ods_counter_check(
                    entity_desc=ods_entity_desc,
                    key_desc="regex(fboss.agent.eth.*discards.sum.60),filter(.*in_discard.*)",
                    validation_expr=f"<= {FPF_ACTIVE_THRESHOLDS.ods_in_discard_max}",
                    reduce_desc=ods_reduce,
                    counter_name="in_discard",
                    shorten_pass_url=True,
                    baseline_excess_max=FPF_ACTIVE_THRESHOLDS.ods_in_discard_max,
                    transient_excess_informational=True,
                    check_id="ods_in_discard",
                ),
                create_fpf_ods_counter_check(
                    entity_desc=ods_entity_desc,
                    key_desc="regex(fboss.agent.eth.*congestion.*sum.60),filter(.*in_congestion_discards.sum.*)",
                    validation_expr=f"<= {FPF_ACTIVE_THRESHOLDS.ods_in_congestion_max}",
                    reduce_desc=ods_reduce,
                    counter_name="in_congestion",
                    shorten_pass_url=True,
                    check_id="ods_in_congestion",
                ),
                create_fpf_ods_counter_check(
                    entity_desc=ods_entity_desc,
                    key_desc="regex(fboss.agent.eth.*congestion.*sum.60),filter(.*out_congestion_discards.sum.*)",
                    validation_expr=f"<= {FPF_ACTIVE_THRESHOLDS.ods_out_congestion_max}",
                    reduce_desc=ods_reduce,
                    counter_name="out_congestion",
                    shorten_pass_url=True,
                    check_id="ods_out_congestion",
                ),
            ]
        )
    elif flip_discards:
        loss_expr = f">= {FPF_ACTIVE_THRESHOLDS.ods_in_discard_max}"
        # "Assert loss occurred": a disable only drops traffic on the impacted
        # path, and in_discard is 0 at most samples. So judge each device's PEAK
        # over the window and pass if ANY device saw loss >= threshold — not
        # every sample on every device (which would never pass).
        postchecks.append(
            create_fpf_ods_counter_check(
                entity_desc=ods_entity_desc,
                key_desc="regex(fboss.agent.eth.*discards.sum.60),filter(.*in_discard.*)",
                validation_expr=loss_expr,
                reduce_desc=ods_reduce,
                counter_name="in_discard",
                shorten_pass_url=True,
                aggregate="max",
                require="any",
                check_id="ods_in_discard_loss_expected",
            )
        )

    # HRT memory/driver stability (ODS-only).
    if hrt_memory_hosts:
        postchecks.append(
            create_fpf_hrt_system_memory_check(
                hosts=hrt_memory_hosts,
                threshold_gib=FPF_ACTIVE_THRESHOLDS.hrt_system_memory_max_gib,
                check_id="fpf_hrt_system_memory",
            )
        )
    if hrt_driver_hosts:
        postchecks.append(
            create_fpf_hrt_driver_disconnect_check(
                hosts=hrt_driver_hosts,
                check_id="fpf_hrt_driver_disconnect",
            )
        )

    # Generic SSH/device-shell postchecks on the DUT GTSWs: services still up,
    # no new core dumps, no unclean exits, memory within bounds after the
    # disruption window.
    snapshot_checks = []
    if include_ssh_checks:
        postchecks.extend(
            [
                create_systemctl_active_state_check(),
                create_device_core_dumps_check(use_start_time=False),
                create_unclean_exit_check(),
                create_memory_utilization_check(
                    threshold=5 * (1024**3),
                    threshold_by_service=_mem_thresholds,
                    start_time_jq_var="test_case_start_time",
                ),
            ]
        )
        snapshot_checks.append(create_core_dumps_snapshot_check())
        # BGP sessions: snapshot the established set at precheck (no fail on
        # baseline-down sessions) and assert it is unchanged post-disruption —
        # a GPU-link disable/drain must not drop any GTSW<->STSW BGP session.
        snapshot_checks.append(
            create_bgp_session_snapshot_check(
                skip_flap_check=True, skip_uptime_check=True
            )
        )

    playbook_kwargs: dict[str, t.Any] = {
        "name": playbook_name,
        "prechecks": prechecks,
        "postchecks": postchecks,
        "snapshot_checks": snapshot_checks,
        "stages": [create_steps_stage(stage_id="disruption", steps=stage_steps)],
    }
    if cleanup_steps is not None:
        playbook_kwargs["cleanup_steps"] = cleanup_steps
    return Playbook(**playbook_kwargs)


def create_fpf_disruption_only_playbook(
    *,
    gtsws: list[str],
    hosts: list[str],
    trigger_stsws: list[str],
    disruption_steps: list,
    playbook_name: str,
) -> Playbook:
    """Bare FPF disruption playbook — runs disruption steps, NO pre/postchecks.

    This is the FIRST half of the two-playbook "longevity-anchored health
    check" pattern. It executes ``disruption_steps`` as a single sequential
    stage and attaches NO prechecks, NO postchecks, and NO snapshot checks, so
    it does nothing but perform the disruption (interface disable/enable, link
    drain/undrain, service kill, etc.).

    Why two playbooks: the TaacRunner stamps a FRESH ``test_case_start_time``
    (both ``jq_vars["test_case_start_time"]`` and the FPF collector-registry
    ``set_test_case_start_time(...)``) at the START of EVERY playbook it runs
    (see ``TaacRunner._run_playbook``). Any FPF check that anchors its query
    window at ``get_test_case_start_time()`` (host-spray, HRT convergence/
    stability, prod-prefix drain, ODS-counter, etc.) therefore measures from
    whichever playbook it lives in — NOT from the overall test-case start.

    The disruptive configs run a disruption phase and then a 5-minute longevity
    phase, and want MOST health checks to measure only the steady-state
    LONGEVITY window (not the noisy disruption window). To achieve that, a
    config lists TWO playbooks:

        playbooks = [
            create_fpf_disruption_only_playbook(
                gtsws=...,
                hosts=...,
                trigger_stsws=...,
                disruption_steps=[...],          # the disruptive actions
                playbook_name="fpf_<case>_disrupt",
            ),
            create_fpf_<...>_longevity_playbook(  # any stable-state playbook
                ...,                              # e.g. a 300s longevity stage
            ),
        ]

    Because the runner stamps a new ``test_case_start_time`` when it starts the
    SECOND (longevity) playbook, every stable-state health check in that
    longevity playbook naturally anchors its window at LONGEVITY START — the
    disruption window is already over and is excluded. The disruption playbook
    here carries no checks, so nothing measures across the disruption itself.

    Args:
        gtsws / hosts / trigger_stsws: FPF topology handles, accepted for
            signature-parity with the other FPF playbook factories (so a config
            can pass the same handles it passes elsewhere). Not otherwise used
            since this playbook runs no checks.
        disruption_steps: Pre-built Steps to run as the single disruption stage.
        playbook_name: Name for this playbook (e.g. ``"fpf_<case>_disrupt"``).

    Returns:
        A ``Playbook`` with empty prechecks/postchecks/snapshot_checks and a
        single ``create_steps_stage`` wrapping ``disruption_steps``.
    """
    return Playbook(
        name=playbook_name,
        prechecks=[],
        postchecks=[],
        snapshot_checks=[],
        stages=[
            create_steps_stage(stage_id="disruption", steps=list(disruption_steps))
        ],
    )


def create_fpf_stays_down_assertion_playbook(
    *,
    playbook_name: str,
    stays_down_steps: list,
    postchecks: list,
    stage_id: str = "stays_down",
) -> Playbook:
    """Bare FPF "stays-down" assertion playbook — runs a short longevity, then
    asserts the impaired steady state.

    This is the SECOND half of the two-playbook "longevity-anchored health
    check" pattern used by tc30-style "stop and never re-enable" tests where
    the system is left in an impaired steady state and the check asserts that
    state holds. The TaacRunner stamps a FRESH ``test_case_start_time`` at
    the START of this playbook (see ``TaacRunner._run_playbook``), so any
    health check anchored at ``get_test_case_start_time()`` measures only the
    post-disruption stable window.

    Args:
        playbook_name: Name for this playbook (e.g.
            ``"fpf_<case>_stays_down"``).
        stays_down_steps: Pre-built Steps to run as the single stays-down
            stage (typically a single ``create_longevity_step``).
        postchecks: Postchecks to assert the impaired steady state — typically
            ``create_fpf_hrt_session_stat_check(mode="stable", ...)`` and any
            related stable-mode checks.
        stage_id: Stage id (default ``"stays_down"``).

    Returns:
        A ``Playbook`` with empty prechecks/snapshot_checks, the supplied
        postchecks, and a single ``create_steps_stage`` wrapping
        ``stays_down_steps``.
    """
    return Playbook(
        name=playbook_name,
        prechecks=[],
        postchecks=list(postchecks),
        snapshot_checks=[],
        stages=[create_steps_stage(stage_id=stage_id, steps=list(stays_down_steps))],
    )


def create_fpf_disrupt_window_playbook(
    *,
    playbook_name: str,
    disruption_steps: list,
    postchecks: list,
    stage_id: str = "disruption",
    spray_hosts: list[str] | None = None,
    ib_traffic_config: t.Mapping[str, t.Any] | None = None,
) -> Playbook:
    """FPF disruption playbook with disruption-window-scoped postchecks.

    Variant of ``create_fpf_disruption_only_playbook`` that ALSO attaches the
    supplied ``postchecks``. Use this when a tc-specific check (typically
    ``create_fpf_hrt_session_stat_check`` in ``mode="disruption"``) must
    measure ACROSS the disruption window — i.e. the postcheck's query window
    must include the disruptive event itself, so the check has to live in the
    same playbook as the disruption stage (since TaacRunner stamps a fresh
    ``test_case_start_time`` at every playbook start). Common pattern for
    tc28/tc29 (fsdb kill / GR stop-and-reenable) where the session-stat check
    must observe both the impaired count and the recovery.

    Args:
        playbook_name: Name for this playbook (e.g. ``"fpf_<case>_disrupt"``).
        disruption_steps: Pre-built Steps to run as the single disruption
            stage.
        postchecks: Postchecks to run at the end of the disruption stage —
            typically a single ``create_fpf_hrt_session_stat_check`` plus any
            additional disruption-window-anchored checks (e.g. host-spray).
        stage_id: Stage id (default ``"disruption"``).
        spray_hosts: When given (>= 2 hosts), a STRICT traffic precheck is
            prepended at the stage HEAD (server = spray_hosts[0], clients = the
            rest) to verify all 4 RDMA planes carry traffic before the
            disruption. No-op when None / < 2 hosts (e.g. skip_ssh).

    Returns:
        A ``Playbook`` with empty prechecks/snapshot_checks, the supplied
        postchecks, and a single ``create_steps_stage`` wrapping
        ``disruption_steps`` (optionally prepended with the traffic precheck).
    """
    from taac.steps.step_definitions import (
        create_fpf_ensure_traffic_step,
    )

    ensure_traffic = (
        [
            create_fpf_ensure_traffic_step(
                **ib_traffic_config,
                description=(
                    "Strict traffic readiness: validate the canonical process "
                    "and egress contract; recover only after the prior verdict"
                ),
            )
        ]
        if ib_traffic_config
        else (
        [
            create_fpf_ensure_traffic_step(
                server=spray_hosts[0],
                clients=list(spray_hosts[1:]),
                description=(
                    "Strict traffic precheck: ensure all 4 planes carry traffic "
                    "(restart ib_write_bw if collapsed; fail hard on a plane wedge)"
                ),
            )
        ]
        if spray_hosts and len(spray_hosts) >= 2
        else []
        )
    )
    steps = ensure_traffic + list(disruption_steps)
    return Playbook(
        name=playbook_name,
        prechecks=[],
        postchecks=list(postchecks),
        snapshot_checks=[],
        stages=[create_steps_stage(stage_id=stage_id, steps=steps)],
    )


def create_fpf_prod_prefix_drain_only_playbook(
    *,
    hosts: list[str],
    disruption_steps: list,
    local_prefixes: list[str],
    remote_prefixes: list[str],
    impacted_planes_by_host: dict,
    mode: str,
    max_drain_sec: float | None = None,
    playbook_name: str = "fpf_prod_prefix_drain_only",
) -> Playbook:
    """Minimal FPF playbook that runs ONLY the prod-prefix local-drain check.

    A focused validation harness for the local-vs-remote drain contract — NO
    test-prefix injection, NO stabilization wait, and NO other health checks.
    The production prefixes are real (already on the fabric), so nothing needs
    injecting; the prod-prefix collector (started by FpfStartCollectorsTask in
    setup_tasks) supplies the pre/post-drain samples. The supplied
    ``disruption_steps`` (drain+longevity or undrain+longevity) record the
    disruption moment themselves, from which the check measures drain latency.

    ``mode`` is "local_drain" (the LOCAL prefix's impacted plane must reach
    DRAINED — not unreachable — within the SLA while REMOTE prefixes don't churn)
    or "local_undrain" (the impacted plane returns to reachable within the SLA).
    """
    from taac.health_checks.healthcheck_definitions import (
        create_fpf_prod_hrt_prefix_stability_check,
    )
    from taac.libs.fpf.fpf_thresholds import (
        ACTIVE as FPF_ACTIVE_THRESHOLDS,
    )
    from taac.stages.stage_definitions import create_steps_stage

    if max_drain_sec is not None:
        sla = max_drain_sec
    elif mode == "local_undrain":
        # Recovery (undrain / re-enable) is inherently slower than a drain.
        sla = FPF_ACTIVE_THRESHOLDS.prod_prefix_recovery_sla_sec
    else:
        sla = FPF_ACTIVE_THRESHOLDS.prod_prefix_drain_sla_sec
    monitored = list(local_prefixes) + list(remote_prefixes)
    postchecks = [
        create_fpf_prod_hrt_prefix_stability_check(
            mode=mode,
            prefixes=monitored,
            local_prefixes=local_prefixes,
            impacted_planes_by_host=impacted_planes_by_host,
            max_drain_sec=sla,
            check_id=f"fpf_prod_prefix_{mode}",
        )
    ]
    return Playbook(
        name=playbook_name,
        prechecks=[],
        postchecks=postchecks,
        snapshot_checks=[],
        stages=[
            create_steps_stage(stage_id="disruption", steps=list(disruption_steps))
        ],
    )


def create_fpf_service_restart_playbook(
    *,
    gtsws: list[str],
    hosts: list[str],
    trigger_stsws: list[str],
    service,
    trigger: taac_types.ServiceInterruptionTrigger = taac_types.ServiceInterruptionTrigger.SYSTEMCTL_RESTART,
    restart_device_regexes: list[str],
    affected_rib: str | None,
    prefix_count: int,
    community_list: str,
    injected_lanes: list[int],
    prod_prefixes: list[str] | None = None,
    hrt_memory_hosts: list[str] | None = None,
    hrt_driver_hosts: list[str] | None = None,
    spray_hosts: list[str] | None = None,
    ods_entities: list[str] | None = None,
    fsdb_expected_total: int = 32,
    stabilization_delay_sec: int = 120,
    settle_after_restart_sec: int = 120,
    create_cold_boot_file: bool = False,
    bgp_reconverge_sla_sec: float | None = None,
    fsdb_reconverge_sla_sec: float | None = None,
    stable_settle_sec: int = 0,
    skip_ssh_dependent_checks: bool = False,
    skip_injection: bool = False,
    rf_vf_groups: list | None = None,
    playbook_name: str = "fpf_service_restart",
    assert_bgp_reconvergence: bool = False,
    reconvergence_sla_sec: float = 60.0,
    skip_fsdb_session_postcheck: bool = False,
    convergence_blip_mode: str = "strict",
    hrt_device_ids: list[int] | None = None,
    ib_traffic_config: t.Mapping[str, t.Any] | None = None,
) -> Playbook:
    """FPF service-restart / coldboot playbook (single playbook, self-recovering).

    ``convergence_blip_mode`` selects the two-mode blip-handling contract for the
    UNAFFECTED-rib stable convergence (Signal-3), the HRT bulk / remote-failure /
    prod-prefix stable checks: "strict" (default, unchanged), "last_sample"
    (MODE A — disruptive coldboot/kill; only the last sample must hold golden), or
    "skip_null_strict" (MODE B — graceful; tolerate null samples but every
    non-null, and the last, must hold golden). The AFFECTED rib keeps its
    null-tolerant mode="restart" reconverge contract regardless.

    ``rf_vf_groups`` (8-STSW split-per-VF injection): a list of
    ``{"suffix", "subnet", "lanes"}`` dicts. When given, the single broad HRT
    remote-failure "stable" check is replaced by one per VF group, each reading
    its narrow-subnet collector and explicit device IDs. Every selected tuple is
    expected to remain at zero.

    ``skip_injection`` drops the in-playbook prefix-injection + stabilization
    stage steps (prefixes injected once by the ``fpf_inject_bgp_prefixes`` setup
    task — 8-STSW split-per-VF injection). ``prefix_count`` then serves only as
    the EXPECTED converged count for the per-GTSW/per-lane checks.

    Injects prefixes, stabilizes, records the restart moment, restarts ``service``
    on ``restart_device_regexes`` (the DUT GTSW), waits ``settle_after_restart_sec``,
    then asserts:

      - HRT (bulk / remote-failure / prod-prefix / plane-status): NO churn — the
        restart is on the GTSW; HRT is queried on the GPU host and is unaffected.
        (For a disruptive coldboot, ``stable_settle_sec`` advances these windows
        past the recovery transient so only the recovered steady state is judged.)
      - The AFFECTED rib (``affected_rib`` = "bgp" for bgpd / wedge_agent restart,
        "fsdb" for an fsdb restart) uses mode="restart": tolerate the
        null/unresponsive polls during the restart and assert the rib returns to
        ``prefix_count`` within the reconverge SLA from the recorded restart.
      - The UNAFFECTED rib stays converged (normal 3-signal, no drop).
      - ``affected_rib=None`` (qsfp_service): both ribs stay converged — identical
        to stable state.

    No SSH/host-spray/discard-loss assertions are added — a graceful restart is
    lossless and host-spray needs live ib traffic. Coldboot
    (``create_cold_boot_file=True``) is the same shape with a longer settle
    (``stable_settle_sec``/``settle_after_restart_sec``) and reconverge SLAs.
    """
    from taac.health_checks.healthcheck_definitions import (
        create_bgp_stale_route_check,
        create_drain_state_check,
        create_fpf_bgp_rib_convergence_check,
        create_fpf_fsdb_ribmap_convergence_check,
        create_fpf_hrt_bulk_convergence_check,
        create_fpf_hrt_fsdb_session_check,
        create_fpf_hrt_plane_status_check,
        create_fpf_hrt_remote_failure_convergence_check,
        create_fpf_prod_hrt_prefix_stability_check,
        create_service_restart_check,
    )
    from taac.libs.fpf.fpf_thresholds import (
        ACTIVE as FPF_ACTIVE_THRESHOLDS,
    )
    from taac.stages.stage_definitions import create_steps_stage
    from taac.steps.step_definitions import (
        create_fpf_bgp_prefix_injection_step,
        create_fpf_ensure_traffic_step,
        create_fpf_record_disruption_time_step,
        create_longevity_step,
        create_service_interruption_step,
    )

    services = ["bgpd", "fsdb", "wedge_agent", "qsfp_service"]
    resolved_hrt_device_ids = hrt_device_ids or sorted(
        {
            int(device_id)
            for group in (rf_vf_groups or [])
            for device_id in group.get("device_ids", [0])
        }
    ) or [0]

    # Generic (non-convergence) check set shared with the hardening playbooks:
    # generic prechecks (with the MANDATORY drain pre-check prepended as the
    # first stage step below), generic postchecks, and snapshot checks.
    generic_prechecks, generic_postchecks, snapshot_checks = _build_fpf_generic_checks(
        hosts=hosts,
        services=services,
        gtsws=gtsws,
        trigger_stsws=trigger_stsws,
        skip_ssh_dependent_checks=skip_ssh_dependent_checks,
        fsdb_sessions_per_host=fsdb_expected_total,
        prod_prefixes=prod_prefixes,
        hrt_memory_hosts=hrt_memory_hosts,
        hrt_driver_hosts=hrt_driver_hosts,
        spray_hosts=spray_hosts,
        ods_entities=ods_entities,
        # A restart/coldboot with live traffic causes expected transient
        # in-flight discards; surface them as informational, not a test failure.
        ods_discard_informational=True,
        skip_fsdb_session_postcheck=skip_fsdb_session_postcheck,
        # Reconvergence-timing assertion, scoped to the restarted device and
        # anchored on the disrupted service's own systemd unit (so the systemctl
        # ActiveEnterTimestamp the check reads is exactly the unit that was
        # restarted). Opt-in per config (e.g. bgp/fsdb/wedge restart + coldboot).
        assert_bgp_reconvergence=assert_bgp_reconvergence,
        reconvergence_service=taac_types.SERVICE_NAME_MAP[service],
        reconvergence_sla_sec=reconvergence_sla_sec,
        reconvergence_hosts=restart_device_regexes,
        hrt_device_ids=resolved_hrt_device_ids,
    )

    # MANDATORY FPF drain pre-check (matches v1): abort if any in-scope GTSW /
    # trigger STSW is drained. One check per device (single-device scoped).
    drain_prechecks = [
        create_drain_state_check(expected_drained=False, device_name=device)
        for device in [*gtsws, *trigger_stsws]
    ]

    bgp_sla = (
        bgp_reconverge_sla_sec
        if bgp_reconverge_sla_sec is not None
        else FPF_ACTIVE_THRESHOLDS.bgp_restart_reconverge_sla_sec
    )
    fsdb_sla = (
        fsdb_reconverge_sla_sec
        if fsdb_reconverge_sla_sec is not None
        else FPF_ACTIVE_THRESHOLDS.fsdb_restart_reconverge_sla_sec
    )
    settle = stable_settle_sec or None

    # Remote-failure "stable" direction selected by ``convergence_blip_mode``:
    #   "last_sample"      -> stable_last_sample (MODE A)
    #   "skip_null_strict" -> stable_skip_null_strict (MODE B)
    #   "strict"/default   -> stable
    if convergence_blip_mode == "last_sample":
        _rf_direction = "stable_last_sample"
    elif convergence_blip_mode == "skip_null_strict":
        _rf_direction = "stable_skip_null_strict"
    else:
        _rf_direction = "stable"

    # When skip_injection, prefixes are injected once by a setup task; the stage
    # starts at the restart-time stamp.
    stage_steps = []
    # STRICT traffic precheck at the stage HEAD: verify all 4 RDMA planes carry
    # traffic (restart ib_write_bw if collapsed; fail hard on a plane wedge).
    # No-op when skip_ssh (spray_hosts is None / < 2 hosts).
    if ib_traffic_config:
        stage_steps.append(
            create_fpf_ensure_traffic_step(
                **ib_traffic_config,
                description=(
                    "Strict traffic readiness: validate the canonical process "
                    "and egress contract; recover only after the prior verdict"
                ),
            )
        )
    elif spray_hosts and len(spray_hosts) >= 2:
        stage_steps.append(
            create_fpf_ensure_traffic_step(
                server=spray_hosts[0],
                clients=list(spray_hosts[1:]),
                description=(
                    "Strict traffic precheck: ensure all 4 planes carry traffic "
                    "(restart ib_write_bw if collapsed; fail hard on a plane wedge)"
                ),
            )
        )
    if not skip_injection:
        stage_steps.extend(
            [
                create_fpf_bgp_prefix_injection_step(
                    devices=trigger_stsws,
                    count=prefix_count,
                    community_list=community_list,
                    description=f"Inject {prefix_count} BGP prefixes on {', '.join(trigger_stsws)}",
                ),
                create_longevity_step(
                    duration=stabilization_delay_sec,
                    description=f"Stabilization wait {stabilization_delay_sec}s before restart",
                ),
            ]
        )
    stage_steps.extend(
        [
            # Stamp the restart moment so the affected-rib reconverge SLA measures
            # from here, not test-case start.
            create_fpf_record_disruption_time_step(),
            create_service_interruption_step(
                service=service,
                trigger=trigger,
                create_cold_boot_file=create_cold_boot_file,
                device_regexes=restart_device_regexes,
                description=f"{'Cold boot' if create_cold_boot_file else 'Restart'} "
                f"service on {restart_device_regexes}",
            ),
            create_longevity_step(
                duration=settle_after_restart_sec,
                description=f"Settle {settle_after_restart_sec}s after restart before assertion",
            ),
        ]
    )

    postchecks = []
    # --- Per-GTSW rib checks: affected rib reconverges (null-tolerant), the
    # other stays converged. ---
    for lane_id, gtsw in enumerate(gtsws):
        lane_map = {str(lane_id): gtsw}
        is_restart_target = any(
            re.search(device_pattern, gtsw)
            for device_pattern in restart_device_regexes
        )
        if affected_rib == "bgp":
            if is_restart_target:
                postchecks.append(
                    create_fpf_bgp_rib_convergence_check(
                        lane_map=lane_map,
                        expected_matched=prefix_count,
                        use_live_collectors=True,
                        mode="restart",
                        reconverge_sla_sec=bgp_sla,
                        check_id=f"fpf_bgp_restart_reconverge_lane{lane_id}",
                    )
                )
            else:
                postchecks.append(
                    create_fpf_bgp_rib_convergence_check(
                        lane_map=lane_map,
                        expected_matched=prefix_count,
                        use_live_collectors=True,
                        settle_sec=settle,
                        stability_mode=convergence_blip_mode,
                        check_id=f"fpf_bgp_stable_lane{lane_id}",
                    )
                )
            postchecks.append(
                create_fpf_fsdb_ribmap_convergence_check(
                    lane_map=lane_map,
                    expected_matched=prefix_count,
                    use_live_collectors=True,
                    settle_sec=settle,
                    stability_mode=convergence_blip_mode,
                    check_id=f"fpf_fsdb_stable_lane{lane_id}",
                )
            )
        elif affected_rib == "fsdb":
            if is_restart_target:
                postchecks.append(
                    create_fpf_fsdb_ribmap_convergence_check(
                        lane_map=lane_map,
                        expected_matched=prefix_count,
                        use_live_collectors=True,
                        mode="restart",
                        reconverge_sla_sec=fsdb_sla,
                        check_id=f"fpf_fsdb_restart_reconverge_lane{lane_id}",
                    )
                )
            else:
                postchecks.append(
                    create_fpf_fsdb_ribmap_convergence_check(
                        lane_map=lane_map,
                        expected_matched=prefix_count,
                        use_live_collectors=True,
                        settle_sec=settle,
                        stability_mode=convergence_blip_mode,
                        check_id=f"fpf_fsdb_stable_lane{lane_id}",
                    )
                )
            postchecks.append(
                create_fpf_bgp_rib_convergence_check(
                    lane_map=lane_map,
                    expected_matched=prefix_count,
                    use_live_collectors=True,
                    settle_sec=settle,
                    stability_mode=convergence_blip_mode,
                    check_id=f"fpf_bgp_stable_lane{lane_id}",
                )
            )
        else:
            # qsfp_service: both ribs stay converged (identical to stable state).
            postchecks.append(
                create_fpf_fsdb_ribmap_convergence_check(
                    lane_map=lane_map,
                    expected_matched=prefix_count,
                    use_live_collectors=True,
                    settle_sec=settle,
                    stability_mode=convergence_blip_mode,
                    check_id=f"fpf_fsdb_stable_lane{lane_id}",
                )
            )
            postchecks.append(
                create_fpf_bgp_rib_convergence_check(
                    lane_map=lane_map,
                    expected_matched=prefix_count,
                    use_live_collectors=True,
                    settle_sec=settle,
                    stability_mode=convergence_blip_mode,
                    check_id=f"fpf_bgp_stable_lane{lane_id}",
                )
            )

    # --- HRT signals: NO churn (queried on the GPU host, unaffected by a GTSW
    # service restart). For a disruptive coldboot, stable_settle_sec skips the
    # recovery transient so only the recovered steady state is judged. ---
    postchecks.append(
        create_fpf_hrt_bulk_convergence_check(
            lanes=injected_lanes,
            device_ids=resolved_hrt_device_ids,
            expected_per_lane={str(lane): prefix_count for lane in injected_lanes},
            use_live_collectors=True,
            settle_sec=settle,
            stability_mode=convergence_blip_mode,
            check_id="fpf_hrt_bulk_stable",
        )
    )
    if rf_vf_groups:
        # Per-VF-group: assert zero on every mapped device/local-plane tuple.
        for _g in rf_vf_groups:
            _glanes, _gexpected = _fpf_rf_stable_scope(_g, injected_lanes)
            if not _glanes:
                continue
            postchecks.append(
                create_fpf_hrt_remote_failure_convergence_check(
                    lanes=_glanes,
                    device_ids=_g.get("device_ids", [0]),
                    expected_per_lane=_gexpected,
                    direction=_rf_direction,
                    use_live_collectors=True,
                    collector_name=f"hrt_remote_failure_{_g['suffix']}",
                    check_id=f"fpf_hrt_remote_failure_stable_{_g['suffix']}",
                )
            )
    else:
        postchecks.append(
            create_fpf_hrt_remote_failure_convergence_check(
                lanes=injected_lanes,
                device_ids=resolved_hrt_device_ids,
                direction=_rf_direction,
                use_live_collectors=True,
                check_id="fpf_hrt_remote_failure_stable",
            )
        )
    if prod_prefixes:
        postchecks.append(
            create_fpf_prod_hrt_prefix_stability_check(
                settle_sec=settle,
                stability_mode=convergence_blip_mode,
                check_id="fpf_prod_hrt_prefix_stable",
            )
        )
        postchecks.append(
            create_fpf_hrt_plane_status_check(
                mode="all_up",
                device_ids=resolved_hrt_device_ids,
                # Scope to the injected/tested lanes so a lab plane that is
                # already impaired at baseline (e.g. an unrelated drained GTSW)
                # is not flagged as a restart regression. Mirrors the
                # injected-lane scoping used by the convergence/bulk/remote-
                # failure checks above.
                expected_planes=injected_lanes,
                settle_sec=settle,
                # Disruptive coldboot/restart (convergence_blip_mode="last_sample")
                # tolerates a mid-window plane UNKNOWN that recovers to UP (latched
                # while HRT re-subscribes); only the last sample must be UP.
                stability_mode=convergence_blip_mode,
                check_id="fpf_hrt_plane_status_all_up",
            )
        )

    # --- FSDB/HRT session: stays fully CONNECTED through the restart. ---
    postchecks.append(
        create_fpf_hrt_fsdb_session_check(
            hosts=hosts,
            expected_session_count=fsdb_expected_total,
            device_ids=(resolved_hrt_device_ids if len(resolved_hrt_device_ids) > 1 else None),
            planes_per_device=(
                len(injected_lanes) if len(resolved_hrt_device_ids) > 1 else None
            ),
            check_id="fpf_hrt_fsdb_session_stable",
        )
    )

    # Process-restart composition: assert ONLY the expected service(s) restarted
    # (no UNEXPECTED collateral restarts) and that no BGP graceful-restart stale
    # routes linger after recovery. The targeted service's systemctl name is
    # resolved from the Service enum via SERVICE_NAME_MAP.
    #
    # Cascade handling: a wedge_agent (AGENT) restart OR an agent coldboot
    # (create_cold_boot_file=True) intentionally cascades and ALSO restarts
    # bgpd/fsdb/qsfp/the split sw+hw agents (BindsTo + ExecStop hooks). Declaring
    # only the targeted service would false-fail the by-design cascade (e.g. tc25
    # FAIL "bgpd restarted during test"), so for those cases we declare the full
    # FPF service set as expected_restarted_services. For every OTHER service
    # (bgpd / fsdb / qsfp_service on their own) we keep just the targeted service
    # so an unexpected collateral restart still trips the check.
    #
    # SERVICE_RESTART_CHECK probes systemctl over SSH, so it is gated behind
    # skip_ssh_dependent_checks (dropped in headless runs without an SSH cert).
    # Its active-state probe is scoped to the FPF ``services`` list — openr is
    # not loaded on GTSW/STSW, so the default service list would false-fail on
    # openr being INACTIVE.
    #
    # When the targeted service is ``AGENT`` (= wedge_agent on FBOSS), three
    # other daemons restart with it via systemd cascade (Pavan-confirmed
    # by-design, T274731352 + T275672046):
    #   - bgpd via ``BindsTo=wedge_agent.service``
    #   - fboss_sw_agent + fboss_hw_agent@0 via the wedge_agent unit's
    #     hand-coded ``ExecStop=pre_wedge_agent_shut_runner.par`` hook
    # The postcheck must whitelist all four so the cascade-restarts are not
    # flagged as collateral. This invariant is enforced at CI time by
    # ``test_wedge_agent_restart_implies_bindsto_cascade_in_expected`` in
    # ``tests/test_service_restart_dependency.py``.
    if not skip_ssh_dependent_checks:
        is_agent_restart = service == taac_types.Service.AGENT
        if is_agent_restart or create_cold_boot_file:
            # Full FPF cascade set restarted by a wedge_agent restart / coldboot.
            expected_restarted_services = [
                "wedge_agent",
                "bgpd",
                "fsdb",
                "qsfp_service",
                "fboss_sw_agent",
                "fboss_hw_agent@0",
            ]
        else:
            expected_restarted_services = [
                taac_types.SERVICE_NAME_MAP.get(service, service.name)
            ]
        postchecks.append(
            create_service_restart_check(
                services=services,
                expected_restarted_services=expected_restarted_services,
            )
        )
    # BGP_STALE_ROUTE_CHECK reads the BGP RIB over thrift (no SSH), so it runs in
    # both full and headless modes.
    postchecks.append(create_bgp_stale_route_check())

    # Prepend the shared generic (non-convergence) check set: generic SSH/device
    # + ODS-only postchecks (HRT mem/driver/spray are included here, replacing the
    # previously-inline ones).
    postchecks = [*generic_postchecks, *postchecks]

    return Playbook(
        name=playbook_name,
        prechecks=[*drain_prechecks, *generic_prechecks],
        postchecks=postchecks,
        snapshot_checks=snapshot_checks,
        stages=[create_steps_stage(stage_id="restart", steps=stage_steps)],
    )


def create_dlb_topology_smoke_playbook(
    name: str = "dlb_topology_smoke_128_width",
    duration_s: int = 120,
) -> Playbook:
    """First-iteration smoke playbook for IcePack GTSW DLB topology setup.

    Validates the topology end-to-end (BGP up, NDP resolved, DLB
    super-group programmed) without exercising disruption/churn loops.
    Single stage: start traffic → longevity → stop traffic.
    """
    return Playbook(
        name=name,
        stages=[
            create_steps_stage(
                stage_id="smoke",
                steps=[
                    create_start_traffic_step(),
                    create_longevity_step(duration=duration_s),
                    create_stop_traffic_step(),
                ],
            ),
        ],
    )


def create_dlb_hardening_playbook(
    name: str,
    setup_steps,
    traffic_steps,
    stickiness_json_params,
    extra_postchecks=None,
) -> Playbook:
    """Factory for one IcePack DLB-hardening test playbook.

    Used by `testconfigs/npi/dlb_hardening_test_config.py` to assemble
    the 23 per-case playbooks (CASE_01 … CASE_23). Splits steps into a
    setup stage (CSV-driven IXIA mutations + Silver toggle) and a
    traffic stage (start → longevity → stop). Postcheck is the
    `DlbResourceStickinessHealthCheck` with per-case `expected_counts`
    derived by the testconfig's `_stickiness_expectations` helper, plus
    any `extra_postchecks` the caller threads in (longevity playbooks
    add CPU + MEM utilization checks here so background-disruption
    cases catch slow leaks / runaway CPU over hours-long windows).

    Kept generic to keep this factory free of the testbed-specific
    helpers (CSV-path map, pool name lookup, expectations derivation)
    that live in the testconfig.
    """
    stages = []
    if setup_steps:
        stages.append(create_steps_stage(stage_id=f"{name}_setup", steps=setup_steps))
    stages.append(create_steps_stage(stage_id=f"{name}_run", steps=traffic_steps))
    postchecks = [
        create_dlb_resource_stickiness_check(json_params=stickiness_json_params),
    ]
    if extra_postchecks:
        postchecks.extend(extra_postchecks)
    return Playbook(
        name=name,
        stages=stages,
        postchecks=postchecks,
    )


def create_be_qos_playbook(
    name: str,
    traffic_items_to_configure: t.Optional[t.Dict[str, TrafficItemSettings]] = None,
    traffic_items_to_start: t.Optional[t.List[str]] = None,
    postchecks: t.Optional[t.List[PointInTimeHealthCheck]] = None,
    snapshot_checks: t.Optional[t.List[SnapshotHealthCheck]] = None,
    stages: t.Optional[t.List[Stage]] = None,
    cleanup_steps: t.Optional[t.List[Step]] = None,
) -> Playbook:
    """Assemble a backend (DSF/RTSW) QoS scheduling `Playbook`.

    Shared by every BE QoS playbook builder in
    `internal/test_configs/be_qos_scheduling_test_config.py` (scheduling,
    per-queue congestion, microburst, 2-queue/3-queue priority, and
    multi-port variants). Those builders compute the stages, checks and
    traffic items; this factory performs the actual construction so it stays
    in the canonical definitions file.

    Args:
        name: Playbook name, e.g. `test_be_qos_scheduling_queue7_nc`.
        traffic_items_to_configure: IXIA traffic items keyed by name.
        traffic_items_to_start: Regexes selecting which items to start.
        postchecks: Point-in-time checks run after the playbook.
        snapshot_checks: Pre/post snapshot-differencing checks.
        stages: Ordered stages to execute.
        cleanup_steps: Steps run unconditionally at teardown.
    """
    return Playbook(
        name=name,
        traffic_items_to_configure=traffic_items_to_configure or {},
        traffic_items_to_start=traffic_items_to_start or [],
        postchecks=postchecks or [],
        snapshot_checks=snapshot_checks or [],
        stages=stages or [],
        cleanup_steps=cleanup_steps or [],
    )


def create_fpf_gar_playbook(
    *,
    name: str,
    description: str,
    prechecks: t.Optional[t.List[PointInTimeHealthCheck]] = None,
    postchecks: t.Optional[t.List[PointInTimeHealthCheck]] = None,
    stages: t.Optional[t.List[Stage]] = None,
    cleanup_steps: t.Optional[t.List[Step]] = None,
    override_duplicate_checks: bool = False,
) -> Playbook:
    """Assemble an FPF GAR validation or recovery playbook.

    GAR testconfigs compute topology-specific checks and trigger steps, while
    this canonical factory owns construction of the Playbook primitive.
    """
    return Playbook(
        name=name,
        description=description,
        prechecks=prechecks or [],
        postchecks=postchecks or [],
        stages=stages or [],
        cleanup_steps=cleanup_steps or [],
        override_duplicate_checks=override_duplicate_checks,
    )


# ── SC9: bounded number of programmed ECMP sets (characteristic 9) ───────────
#
# 128 eBGP peers per AFI all advertise the SAME 5,000 prefixes, so each prefix
# should install as ONE ECMP set per AFI, 128 next-hops wide. Draining every
# peer in a single commit makes prefixes transiently resolve over different
# surviving subsets, which is what allocates extra sets. The characteristic is
# that the peak stays inside the hardware table and the structure collapses
# back afterwards.
#
# NOT in playbooks/routing/bgp_ebb_playbooks.py on purpose: a catalog
# governance test pins that module's __all__ to exactly twenty names in order,
# so an addition there forces editing the test. SC1-SC6 set the precedent of
# living here instead.

# The device's own EcmpLevel2 (Routing) capacity on bag013.ash6, read from
# `show hardware capacity`. Used as the raw-count ceiling so the periodic task
# has a hardware-anchored bound rather than the historical literal 50, which is
# 0.6% of it and has no derivation.
_SC9_ECMP_LEVEL2_CAPACITY = 8192

# A group must be at least this wide to count as a real ECMP set. The raw
# nexthop-group count includes width-1 groups, so a collapse into per-peer
# singletons makes it RISE -- a ceiling on the raw count therefore fires on a
# LOSS of ECMP. Observed on bag013: healthy {128: 2}, collapsed {1: 256}.
_SC9_MIN_ECMP_WIDTH = 2

# Every prefix should resolve over every peer.
_SC9_EXPECTED_MULTIPATH_WIDTH = 128

# The eBGP prefix pools BOUNDED_ECMP builds: three per AFI (42/42/44 peers).
# Named explicitly so the drain stage can assert it mutated the pools it meant
# to -- a regex that silently matched nothing would otherwise be a green run
# that withdrew nothing.
_SC9_EBGP_PREFIX_POOLS: t.List[str] = [
    f"PREFIX_POOL_{afi}_EBGP_SET{ordinal}"
    for afi in ("IPV4", "IPV6")
    for ordinal in (1, 2, 3)
]


# Ceiling on REAL ECMP sets (>= _SC9_MIN_ECMP_WIDTH wide) at any sample.
#
# Two observations bound this, and neither is a guess. The first fully clean
# single-drain run peaked at 12 multi-way groups (and zero width-1 groups) for a
# 75.6s plateau, against a steady state of exactly 2 -- corroborated by the
# device's own ECMP high watermark moving 7 -> 12 across the same window, an
# independent max-over-time counter that cannot miss a sub-sample peak. The
# worst peak ever recorded on this topology is 27, from the ten-cycle run whose
# cycles re-withdrew mid-recovery; that is a pathological shape this playbook no
# longer produces, but 32 clears even it.
#
# So: 2.7x the clean observation, above the worst contaminated one, 8x under the
# topology's structural maximum of 128*2+2 = 258, and 256x under the device's
# 8,192-entry EcmpLevel2 table. Stated plainly because an earlier version of
# this comment claimed "~5x" against a peak of 6 that a later, cleaner run
# superseded -- the margin is real but it is 2.7x, not 5x.
#
# ★ NOW DERIVED FROM A COMPLETE FIVE-CYCLE RUN, which is the first one there has
# ever been. Five clean draws peaked at ELEVEN multi-way sets (plus a single
# width-1), against twelve total nexthop groups; the one earlier clean draw, at
# one cycle, peaked at 12. So the distribution is tight and -- the part that
# matters -- the peak does NOT grow with cycle count.
#
# That falsified the reasoning behind an interim raise to 64. The argument was
# that N cycles is N draws so the expected maximum climbs with N, anchored on a
# reading of 20 from a two-and-a-bit-cycle run. But that 20 was not a clean
# draw: it was taken while the drain was dying mid-transition with the restore
# ALSO failing, so the device was in a non-recovered state when the maximum
# landed. Discard it and the observations are 11 and 12.
#
# 32 is ~2.9x the five-cycle peak, still 8x under the topology's structural
# maximum of 258 and 256x under the device's 8,192-entry table. 64 would need
# fragmentation to go six-fold worse than anything observed before it said a
# word, which is not a gate.
#
# Being honest about what this number is: it is FITTED to observation, not
# derived from hardware, and it exists to catch an order-of-magnitude explosion.
# The claim itself rests on the calibration-free assertions -- settled at exactly
# 2 per AFI, no groups left unprogrammed, and RIB-level recovery to the
# discovered baseline.
_SC9_MAX_MULTIWAY_GROUPS = 32

# The number of distinct ECMP sets this topology can structurally produce: one
# per eBGP peer per AFI, plus the two converged sets. Used as the bound on how
# far the device-maintained ECMP high watermark may climb ACROSS the drain.
#
# A structural bound, not a calibrated one, and labelled as such: the clean
# single-drain run moved that watermark by 5, so 258 is ~50x that observation
# and cannot false-fail on variance.
#
# ★ READ THIS BEFORE TRUSTING A PASS. The watermark is a max-SINCE-BOOT counter
# that no SC9 step can reset, so this delta only discriminates when SC9's own
# peak would exceed the peak the box already carried. It usually will not. The
# 5-cycle run measured `ecmp_high_watermark` 241 -> 241 across the entire drain,
# because the full-scale run that preceded it on the same boot had already set
# 241 and a bounded-ECMP drain peaks around a dozen. The gate PASSED and proved
# nothing -- the same vacuity as a ceiling of 8192 on a topology that cannot
# reach it.
#
# What is NOT vacuous in that step is `max_current_delta` on `ecmp_used`: the
# same run read 2 before the drain and 2 after, i.e. the steady state is two
# ECMP sets and it recovered exactly, asserted at the hardware layer rather
# than from a CLI sample. That is the half of this gate that earns its place.
# The watermark half is worth keeping only because it costs nothing and becomes
# meaningful on a freshly reloaded box.
_SC9_STRUCTURAL_MAX_ECMP_SETS = 258


# Key for the pre/post hardware-capacity capture pair.
#
# `create_hardware_capacity_delta_step` rejects anything that is not a UUID
# (`_validate_persisted_step_key`), so this cannot be a readable slug. uuid5 --
# not uuid4 -- because the key is SERIALIZED into the TestConfig: a random one
# would move the golden manifest on every regeneration and make the diff
# unreviewable. Derived from the device name so two devices running this
# playbook in one runner cannot share a baseline, matching the `_case_key`
# idiom in testconfigs/routing/factories/bgp_ug_2_7_suite.py.
def _sc9_capacity_state_key(device_name: str) -> str:
    return str(
        uuid.uuid5(
            uuid.NAMESPACE_URL,
            f"{device_name}:bgp_ebb_bounded_ecmp_sc9:hardware-capacity",
        )
    )


# Closing-window size for the settled-state verdict. ODD: statistics.median
# averages the two middle samples of an even window, so a window straddling 2
# and 3 medians to 2.5, which can never equal the integer 2 -- a healthy device
# would BREACH. The first green run logged "settled at 2.0" and survived only
# because all ten of its closing samples happened to be identical.
#
# 31 samples is 155s at the 5s poll interval, comfortably inside the ~527s of
# genuine steady state that follows the drain (restore + quiet window + Stage C
# soak) and well before teardown.
_SC9_CONVERGED_WINDOW_SAMPLES = 31

# Floor on how many samples the poll must collect. The first clean run collected
# 195 over a run strictly shorter than the multi-cycle shape this playbook now
# produces, so 150 keeps >=30% margin against the only measured value while
# still failing a run that lost more than half its reads. A liveness floor, not
# a completeness assertion -- the exact count is reported eitherway.
_SC9_MIN_SAMPLES = 150

# The drain step enforces this as a HARD pass/fail on BOTH transitions --
# `_wait_transition` demands ConvergenceOutcome.WITHIN_SLA and raises otherwise
# -- so it is a failure threshold, not a report. Its 60s runtime default is
# SHORTER than this topology's measured 73s restore, which would have failed a
# healthy bag013 on the re-advertise. 180s is ~2.5x the observation, matching
# the margins used for the drain windows; the 300s hard timeout above it is
# untouched.
_SC9_TRANSITION_SOFT_THRESHOLD_SECONDS = 180.0

# One ECMP set per address family is the converged expectation -- the spec's
# "Check that BGP installs 5K routes with 1 ECMP set (NHG)", times two AFIs.
_SC9_AFI_COUNT = 2

# Steady state is DETECTED, not assumed. The baseline the recovery gate is
# measured against has to be a converged one, and the only prior timing datum
# for this testbed -- 382s to INITIALIZED on release 191 -- is both longer than
# the stock 300s settle and inflated by EOR wait on 132 IDLE iBGP peers that
# cannot affect multipath width. That number is therefore useless for sizing a
# blind sleep in either direction, which is the argument for not using one.
#
# A ceiling, not a duration: the step returns as soon as the width holds, so a
# healthy run never pays this. 600s is the SC9 profile's own already-sanctioned
# BGP convergence SLA (`convergence_threshold`), reused rather than invented.
# This predicate is strictly cheaper to satisfy than that check -- it reads the
# multipath width directly and never waits on EOR, which is what made 87% of
# that 382s dead time -- so the same bound is generous here.
_SC9_BASELINE_HARD_TIMEOUT_SECONDS = 600.0
# Each poll is a full dual-AFI RIB walk over 5,000 prefixes x 128 peers, and
# the underlying fetch is itself @async_retryable(retries=50, sleep_time=1).
_SC9_BASELINE_POLL_INTERVAL_SECONDS = 15.0
# Must clear several poll intervals: observe_convergence restarts this window
# on ANY failing observation and on any predicate error, so a value near the
# poll interval would be satisfied by a single lucky read.
_SC9_BASELINE_STABILITY_WINDOW_SECONDS = 30.0
# One hung RIB read must not consume the whole budget.
_SC9_BASELINE_PREDICATE_TIMEOUT_SECONDS = 120.0
# The poll does the waiting now. This is only enough for sessions to start
# coming up so the first read is not certainly wasted; the stock default is 300.
_SC9_SETUP_SETTLE_SECONDS = 60


def get_bgp_ebb_bounded_ecmp_sc9_playbook(
    device_name: str,
    expected_multipath_width: int = _SC9_EXPECTED_MULTIPATH_WIDTH,
    # Both derived from the first clean bag013 run, not from taste. The
    # withdrawal cleared in ~41s (last 2-group sample 35s after the withdraw,
    # first 0-group sample at 41s) and full recovery took ~73s (first transient
    # sample 4s after the re-advertise, back to the steady 2 at 73s).
    #
    # They are deliberately ASYMMETRIC, which the original 600/600 was not, and
    # the asymmetry is not cosmetic -- the two windows do different jobs. The
    # count sits flat at 0 for the whole withdraw window and NOTHING SC9
    # measures happens there, so that window only has to let the withdrawal land
    # and hold. The readvertise window is
    # where the entire characteristic lives -- the clean run's series was
    # 2 -> 0 -> 12 -> 2 and the 12 is on THIS side -- so it must contain the
    # whole transient and let it settle before the next cycle withdraws again.
    #
    # 180s for that is 2.5x the 73s observation, and it is chosen to equal
    # `transition_soft_threshold_seconds` on purpose. The dwell is
    # `max(0, R - elapsed)` with no error path, so the only way to shrink it to
    # zero -- and start the next withdraw on top of an unfinished recovery -- is
    # a transition that took the whole 180s, which has already breached the soft
    # threshold and hard-failed the run. The overlap that contaminated run 1
    # therefore cannot happen silently.
    #
    # That argument covers the READVERTISE side only, and deliberately so: W is
    # below the same 180s soft threshold, so a slow withdraw yields a zero dwell
    # with no failure and the withdraw side has no equivalent guarantee.
    #
    # W IS NOW MEASURED, and the first sizing was WRONG. It was set to 60 by
    # inferring the RIB convergence time from a FIB observation of 41s. The
    # 5-cycle run -- the first to log the drain step's own record, which every
    # passing run before it discarded -- reported withdraw `elapsed_seconds` of
    # 68.5, 59.2, 59.0, 59.4, 59.2. Cycle 1 overran W outright and the other
    # four cleared it by under a second, so the dwell was effectively ZERO on
    # all five and the flat-0 window described above did not exist. The
    # underlying convergence is remarkably stable at 50.2-50.4s; the extra ~9s
    # is confirmation plus poll granularity.
    #
    # 120 is ~1.75x the worst observed elapsed and ~2.4x the convergence, which
    # buys a real 51-61s drained hold. Sized from the measurement rather than
    # from the soft threshold on purpose: 180 would be symmetric with R but
    # would spend five extra minutes covering a tail the data says is not there.
    #
    # For the record: the stage's own 60/60 default would be too SHORT -- a 60s
    # readvertise window ends 13s before recovery completes. Ten cycles of that
    # is the mechanism behind run 1's peak of 27 sets and its 20 eBGP session
    # restarts, where each cycle re-withdrew mid-recovery.
    withdraw_seconds: int = 120,
    # Also measured now, and correctly sized: advertise elapsed ran 69.4-75.7s
    # on four cycles and 113.9s on one outlier (7 convergence attempts against
    # 3, convergence 104.1s against ~60s). Worst case still leaves a 66s dwell,
    # and all ten transitions stayed WITHIN_SLA against the 180s soft threshold.
    readvertise_seconds: int = 180,
    # FIVE drains, not one.
    #
    # One clean draw of 12 against a ceiling of 32 is a realized margin of 2.7x
    # resting on a single observation, which is not enough to call the count
    # bounded -- SC9's headline claim. Five gives a distribution: run-to-run
    # spread, whether the peak grows across cycles (it should not; each cycle
    # starts from a fully recovered device), and whether the steady state really
    # returns to 2 every time rather than once.
    #
    # The cost is bounded and the risk is understood. Five cycles is 10
    # transitions rather than 2, so 10 chances to breach the 180s soft threshold
    # instead of 2 -- that is a real increase in exposure, and it is intended: a
    # transition that slow IS the finding. `transition_soft_threshold_seconds`
    # and the 300s hard timeout above it are deliberately NOT relaxed to
    # compensate.
    cycles: int = 5,
    soak_duration_seconds: int = 300,
) -> Playbook:
    """Build the SC9 bounded-ECMP-sets characteristic playbook.

    Gates, and why each sits where it does:

    * Steady state (Stage A) -- an in-sequence discovery step POLLS the modal
      multipath width per AFI until it reads ``expected_multipath_width`` and
      HOLDS there for the stability window, then records it together with the
      prefix set at that width; it fails if that never happens inside the hard
      timeout. Detected rather than assumed: the recovery postcheck is scored
      against this baseline, so a width captured mid-convergence would let a
      genuinely degraded run "recover" to the wrong number. It is a Stage step
      rather than a precheck because ``--continue-on-precheck-failure`` (used by
      the canonical dev run command) swallows precheck failures wholesale, which
      would silently skip the baseline the recovery gate depends on -- and it
      passes ``stage=POST_TEST`` because being a Stage step is NOT by itself
      enough to block: ``ValidationStep.run`` raises only for PRE_TEST and
      POST_TEST, so the unset default (and MID_TEST) would log the failure and
      carry on regardless of ``fail_fast``.
    * Drain (Stage B) -- ``cycles`` withdrawals of every eBGP pool, each in ONE
      commit. Two separate knobs control that, and an earlier revision only set
      one of them. ``spread=False`` makes a single cycle's withdraw one commit
      across every matched pool rather than three sequential batches
      (``spread=True`` also silently ignores ``prefix_pool_regex``). The NUMBER
      of cycles is not a parameter of the stage at all -- it comes out of
      ``iterations = test_duration_seconds // (withdraw_time +
      readvertise_time)``, which is why the duration is computed here as an
      exact multiple rather than passed as a literal. The two waits are the
      observation windows either side of each restore.
    * Recovery -- asserted by the SC9 profile's postcheck against the discovered
      baseline, not by the periodic task. A task verdict can never be recorded
      as Requirement Coverage (the catalog admits only precheck / workload /
      postcheck / snapshot phases), and the task's own baseline window would
      land during setup_steps, before convergence.
    * Hardware headroom -- two things, which an earlier revision conflated. The
      profile's pre/post hardware-capacity checks bound the device-maintained
      ``ecmp_high_watermark`` in ABSOLUTE terms at both ends, so a peak the box
      arrived carrying is attributed to the testbed rather than to this drain.
      Separately, the capture/compare pair in Stages A and C is the only thing
      that COMPARES those two readings: each hardware-capacity check is
      independent and stateless, so before this the watermark was measured twice
      and differenced never. That delta is the one gate here immune to sampling
      -- a max-over-time counter maintained by the device cannot miss a peak
      that falls between two 5s polls.
    * Instrument liveness -- the periodic task's ``min_observed_groups``, which
      fails a run that reported only zeroes. That is not hypothetical: the
      predecessor suite on bag012 read 0 for all 884 samples and passed eleven
      times on a structurally blind gate.
    """
    # A vacuous drain is the failure mode this suite keeps rediscovering, and
    # cycles=0 is the cheapest route to one: the derived duration would be 0,
    # `iterations` would floor to 0, and the stage would withdraw nothing while
    # every gate below passed on an idle device.
    if cycles < 1:
        raise ValueError(f"SC9 requires at least one drain cycle, got {cycles}")
    profile_checks = get_profile_checks(CheckProfile.SC9_BOUNDED_ECMP, ProfileContext())
    # The drain below runs with fail_on_session_flap=False, which hands the
    # session-stability verdict to the BGP_SESSION_CHECK snapshot. That is only
    # a sound trade if the snapshot check is actually present -- otherwise a
    # flapped peer is recorded in the step's log and gates nothing, which is the
    # silently-inert-gate failure this suite exists to eliminate. Assert the
    # handoff target rather than documenting it in a comment nobody re-reads.
    if not any(
        check.name is hc_types.CheckName.BGP_SESSION_CHECK
        for check in profile_checks.snapshot_checks
    ):
        raise ValueError(
            "SC9 runs its drain with fail_on_session_flap=False, so the "
            "SC9_BOUNDED_ECMP profile MUST carry a BGP_SESSION_CHECK snapshot "
            "check to own the session-stability verdict"
        )
    return Playbook(
        name="bgp_ebb_bounded_ecmp_sc9_playbook",
        description=(
            "SC9: programmed ECMP sets stay within the hardware table during a "
            "simultaneous 128-peer drain, and collapse back afterwards"
        ),
        setup_steps=create_bgp_instability_setup_steps(
            device_name=device_name,
            # Trimmed from the stock 300s because Stage A now polls: the wait
            # that matters is the one with a predicate behind it.
            convergence_wait_seconds=_SC9_SETUP_SETTLE_SECONDS,
        ),
        prechecks=profile_checks.prechecks,
        postchecks=profile_checks.postchecks,
        snapshot_checks=profile_checks.snapshot_checks,
        periodic_tasks=create_standard_periodic_tasks(
            device_name=device_name,
            memory_threshold=Gigabyte.GIG_5.value,
            cpu_util_terminate_on_error=False,
            memory_terminate_on_error=False,
        )
        + [
            create_nexthop_group_poll_periodic_task(
                device_name=device_name,
                # Hardware-anchored rather than the historical literal 50.
                threshold=_SC9_ECMP_LEVEL2_CAPACITY,
                # Blocking: a run that only ever reported zero measured nothing.
                min_observed_groups=1,
                # The device's own report that it could not program a group --
                # the most direct hardware-exhaustion signal available, and the
                # one number that does not need calibrating. Measured 0 on all
                # 728 readings of the first bag013 run, against a peak of 27
                # groups in an 8,192-entry table, so this is a real gate rather
                # than a threshold picked to pass.
                max_unprogrammed=0,
                # Tolerate groups momentarily IN FLIGHT; gate on groups that
                # stay unprogrammed. The first complete five-cycle run read 0
                # in 390 of 391 samples and 4 in exactly one, caught mid-rebuild
                # with widths climbing 1,2,3,12,...,26 and back to 0 five
                # seconds later. `max_unprogrammed=0` alone asserted that
                # creation and hardware programming are atomic, which they are
                # not, so it failed a run whose every other gate passed.
                #
                # 3 samples is ~18s at the measured 5.8s cadence, against an
                # unprogrammed condition that lasted ONE sample (~5s): the poll
                # read 0 groups for five samples, then 3 groups at widths 1/2/3,
                # then 12 groups with 4 unprogrammed, then 9 groups with 0. Note
                # this is the duration of the UNPROGRAMMED state, not of the
                # rebuild -- the rebuild itself runs ~70s to {128: 2} (76/71/68/
                # 70s across the four sampled cycles), so a tolerance sized to
                # the rebuild would be four times too wide and would blind the
                # gate. Anything genuinely unprogrammed persists far longer than
                # 18s -- rel-191 sat at 8 while the ECMP structure was
                # collapsing. Caveat: n=1, one non-zero reading in five cycles.
                unprogrammed_tolerance_samples=3,
                # Report real ECMP sets separately from width-1 singletons. No
                # ceiling yet -- the peak has never been measured on an
                # uncontaminated run, and the coverage-bearing bound is the
                # hardware-capacity postcheck.
                min_ecmp_width=_SC9_MIN_ECMP_WIDTH,
                # Bound the transient on REAL ECMP sets -- see the constant.
                max_multiway_groups=_SC9_MAX_MULTIWAY_GROUPS,
                # SC9's FIRST claim, and until now the only one untested: 5,000
                # routes from 128 peers install as ONE ECMP set per AFI. Every
                # other verdict on this task is a maximum over the run, so a
                # device idling at 5 sets passed identically to one at 2. The
                # first clean run settled at exactly 2 for its closing 910s.
                expected_converged_multiway_groups=_SC9_AFI_COUNT,
                # ODD, and wider than the default -- see the constant.
                converged_window_samples=_SC9_CONVERGED_WINDOW_SAMPLES,
                # The poll swallows every collection failure and only an
                # entirely empty series fails, so without this a run that lost
                # most of its reads scores every verdict above on the survivors.
                min_samples=_SC9_MIN_SAMPLES,
            ),
        ],
        stages=[
            create_steps_stage(
                steps=[
                    create_multipath_nexthop_count_health_check_step(
                        discover_baseline=True,
                        expected_min_baseline_width=expected_multipath_width,
                        expected_max_baseline_width=expected_multipath_width,
                        required_address_families=["ipv4", "ipv6"],
                        # POLL for steady state rather than trusting a settle.
                        # A baseline captured mid-convergence is worse than a
                        # late one: the recovery postcheck compares against it,
                        # so an under-measured width would let a genuinely
                        # degraded run "recover" to the wrong number.
                        convergence_hard_timeout_seconds=(
                            _SC9_BASELINE_HARD_TIMEOUT_SECONDS
                        ),
                        convergence_poll_interval_seconds=(
                            _SC9_BASELINE_POLL_INTERVAL_SECONDS
                        ),
                        convergence_stability_window_seconds=(
                            _SC9_BASELINE_STABILITY_WINDOW_SECONDS
                        ),
                        convergence_predicate_timeout_seconds=(
                            _SC9_BASELINE_PREDICATE_TIMEOUT_SECONDS
                        ),
                        # BLOCKING. Without a stage, ValidationStep.run leaves
                        # exception_cls None and the step merely logs its
                        # failure -- so an unusable baseline would sail into the
                        # drain and only surface later as "no baseline width
                        # discovered" from the recovery postcheck, pointing at
                        # the wrong thing. POST_TEST is the value that maps to
                        # TestCaseFailure; the name is about the exception, not
                        # about where the step sits.
                        stage=taac_types.ValidationStage.POST_TEST,
                        description=(
                            "SC9 Stage A: poll until the per-AFI multipath "
                            f"baseline holds at {expected_multipath_width} "
                            "next-hops, then record it"
                        ),
                    ),
                    # Capture the device's own FEC/ECMP peak counters, AFTER the
                    # baseline has converged so the reading is a steady state
                    # rather than a mid-convergence one.
                    #
                    # This closes the single largest measurement gap in the
                    # suite. The ECMP high watermark was already being read at
                    # both the precheck and the postcheck -- it moved 7 -> 12
                    # across the first clean run -- and NOTHING compared the two
                    # readings, because each hardware-capacity check is
                    # independent and stateless. The pair below is the only
                    # thing in SC9 that compares them, and the only signal here
                    # that is immune to sampling: a max-over-time counter the
                    # device maintains itself cannot miss a transient that falls
                    # between two 5s polls, which is exactly how the nexthop
                    # group poll could walk past a fragmentation event.
                    create_hardware_capacity_delta_step(
                        device_name,
                        "capture",
                        _sc9_capacity_state_key(device_name),
                        description=(
                            "SC9 Stage A: capture the FEC/ECMP capacity "
                            "counters at the converged baseline"
                        ),
                    ),
                ],
            ),
            create_validated_bgp_route_oscillations_stage(
                device_name=device_name,
                prefix_pool_regex=".*EBGP.*",
                expected_prefix_pool_names=_SC9_EBGP_PREFIX_POOLS,
                # The eBGP population, after IBGP_MIMIC_PARENTS scopes the mimic
                # groups out. 128 peers per AFI.
                expected_established_sessions=SC9_EBGP_SESSION_COUNT,
                parent_prefixes_to_ignore=IBGP_MIMIC_PARENTS,
                prefix_start_index=0,
                prefix_end_index=5000,
                # The cycle count is DERIVED, never passed. The stage computes
                #   iterations = test_duration_seconds // (withdraw + readvertise)
                # so the duration has to be an exact multiple of one cycle or
                # the floor division silently drops a drain -- the original
                # 1200/60/60 produced TEN cycles when one was intended, and the
                # revision that fixed it pinned the total to a single cycle,
                # which then made a multi-cycle run impossible to ask for.
                # Multiplying here is the only shape that keeps the requested
                # count and the derived count equal by construction.
                withdraw_time=withdraw_seconds,
                readvertise_time=readvertise_seconds,
                test_duration_seconds=cycles * (withdraw_seconds + readvertise_seconds),
                transition_soft_threshold_seconds=(
                    _SC9_TRANSITION_SOFT_THRESHOLD_SECONDS
                ),
                # Record a flapped peer instead of aborting the drain on it.
                #
                # Reset/flap counters are monotonic and compared against the
                # pre-transition baseline, so a single flap made the
                # convergence predicate permanently unsatisfiable: the
                # transition burned its timeout and so would every transition
                # after it. Two consecutive runs died that way -- one in cycle
                # 3, one in cycle 1 of 5 -- and neither produced the multi-cycle
                # ECMP peak this test exists to measure. It also reported a
                # session event as `transition NOT_CONVERGED`, which is the
                # wrong diagnosis of the wrong thing.
                #
                # This does NOT make the run green on a flap. The
                # BGP_SESSION_CHECK snapshot detected the same event
                # independently on both of those runs, names the peer, and
                # fails the run on its own -- asserted above, not assumed. What
                # changes is that the other nine transitions still execute.
                fail_on_session_flap=False,
            ),
            create_steps_stage(
                steps=[
                    create_longevity_step(
                        duration=soak_duration_seconds,
                        description=(
                            "SC9 Stage C: soak so the transient can collapse "
                            "before the recovery postcheck samples it"
                        ),
                    ),
                    # The other half of the capture above, and the bound the
                    # constant explains. `max_current_delta` is left at the
                    # framework default: post-soak the device is back at its
                    # steady state so the `used` delta should be ~0, but
                    # recovery is already asserted twice over -- at RIB level by
                    # the multipath-width postcheck and on the sampled series by
                    # the converged verdict -- so it is corroboration here, not
                    # the gate. The watermark INCREASE is the gate.
                    create_hardware_capacity_delta_step(
                        device_name,
                        "compare",
                        _sc9_capacity_state_key(device_name),
                        max_high_watermark_increase=_SC9_STRUCTURAL_MAX_ECMP_SETS,
                        description=(
                            "SC9 Stage C: compare FEC/ECMP capacity against the "
                            "pre-drain capture"
                        ),
                    ),
                ],
            ),
        ],
        # Idempotent, and runs in the runner's `finally` so it executes on the
        # failure path too. Without it the captured baseline outlives the test
        # case in the runner-scoped jq vars, and `capture` REFUSES to overwrite
        # an existing key -- so a second attempt in the same runner process
        # would fail in Stage A for a reason that has nothing to do with SC9.
        cleanup_steps=[
            create_hardware_capacity_delta_step(
                device_name,
                "clear",
                _sc9_capacity_state_key(device_name),
                description=(
                    "SC9 cleanup: drop the captured hardware-capacity baseline"
                ),
            ),
        ],
    )
